// One learner goal (canDo) and 4+ specific sub-goals per B1 lesson, shared by all three sheets
// (docs/LESSON_QUALITY_CONTRACT.md A1–A3, owner 2026-10-12). Lessons 1–50 come from their reviewed Avasta sheets,
// 51–75 were rewritten from the generic course defaults. Block goal ids (g_vocab, g_read, g_notice, g_use) stay.
export const B1_LESSON_GOALS = {
  "a2b1-001": {"canDo": "Ma räägin ilma abita endast, loen lühikest teksti, kirjutan õpetajale lühikese sõnumi ja saan teada, mida pean harjutama.", "goals": {"g_read": "Õpilane valib igapäevases olukorras sobiva lause ja leiab Eesti keelte tekstist arvud ja faktid (emakeeled, võõrkeeled, protsendid).", "g_notice": "Õpilane näitab, kuidas ta kasutab viit A2 vormi: kohakäänded, lihtminevik ja eitus, osastav, ma- ja da-vorm ning viisakas palve.", "g_use": "Õpilane räägib ilma abita 30–60 sekundit endast ja kirjutab õpetajale 30–50-sõnalise sõnumi; õpetaja märgib lähtepunkti."}, "tags": {"001_d_cold": "g_use"}},
  "a2b1-002": {"canDo": "Ma kirjutan oma õpetajale 30–60-sõnalise sõnumi: miks ma hiljaks jäin, millal ma kohale jõudsin ja mida ma järgmisel korral teisiti teen.", "goals": {"g_vocab": "Õpilane kasutab hilinemise ja ühistranspordi sõnu: hiljaks jääma, maha jääma, magama jääma, sõiduplaan, peatus, ummik, õnneks, kahjuks.", "g_read": "Õpilane leiab tekstist „Kuidas Eestis tööle ja kooli jõutakse?” fakte Eesti ajakasutuse ja Tallinna ühistranspordi kohta ning võrdleb neid oma eluga.", "g_notice": "Õpilane moodustab lihtmineviku jaatava ja eitava vormi (jäin, buss ei tulnud) ja paneb ajasõna järel tegusõna teisele kohale.", "g_use": "Õpilane räägib oma hilinemisest ja kirjutab oma päris õpetajale sõnumi: mis juhtus, millal ta kohale jõudis ja mida teeb teisiti."}, "tags": {"002_d_hook": "g_vocab", "002_t_exit": "g_vocab", "002_d_read": "g_read", "002_d_think": "g_read", "002_p_story": "g_notice", "002_p_sent": "g_notice", "002_t_msg": "g_use", "002_t_home": "g_use"}},
  "a2b1-003": {"canDo": "Ma räägin oma liikumisharjumustest ja annan sõbrale kaks nõu, kuidas rohkem liikuda.", "goals": {"g_vocab": "Õpilane kasutab liikumise ja harjumuste sõnu: liikuma, harjumus, soovitus, tervislik, trepp, regulaarselt, vähemalt, piisavalt, istuma.", "g_read": "Õpilane leiab Tervise Arengu Instituudi andmetest, kui palju Eesti inimesed liiguvad ja mida soovitused ütlevad, ning võrdleb ennast nendega.", "g_notice": "Õpilane kasutab osastavat sihitist (joon kohvi, ei söö kooki) ja valib ma- või da-vormi (pean liikuma, tahan joosta).", "g_use": "Õpilane küsib sõbra päeva kohta, annab kaks sobivat nõu, reageerib takistustele ja lepib kokku esimese sammu."}, "tags": {"003_d_move": "g_vocab", "003_t_exit": "g_vocab", "003_d_facts": "g_read", "003_d_think": "g_read", "003_p_reply": "g_notice", "003_p_sent": "g_notice", "003_t_advice": "g_use", "003_t_home": "g_use"}},
  "a2b1-004": {"canDo": "Ma helistan keelekooli, selgitan, miks mulle tunniaeg ei sobi, ja lepin viisakalt kokku uue aja.", "goals": {"g_vocab": "Õpilane kasutab kursuse ja aja sõnu: tunniaeg, sobima, muutma, vaba koht, registreeruma, hõivatud, internetis, kokku leppima.", "g_read": "Õpilane saab aru keelekooli automaatvastajast (päevad, kellaajad, vabad kohad, hind) ja valib endale sobiva aja.", "g_notice": "Õpilane valib kus-, kuhu- ja kust-vormi (tööl, koju, koosolekult) ja palub tingiva kõneviisiga (Kas te saaksite …? Kas sobiks …?).", "g_use": "Õpilane räägib minuti ilma abita oma nädalast, helistab administraatorile, reageerib takistusele ja lepib uue tunniaja kokku."}, "tags": {"004_d_now": "g_vocab", "004_t_exit": "g_vocab", "004_d_info": "g_read", "004_d_think": "g_read", "004_p_chat": "g_notice", "004_p_place": "g_notice", "004_p_sent": "g_notice", "004_t_phone": "g_use", "004_t_home": "g_use"}},
  "a2b1-005": {"canDo": "Ma loen lühikesi igapäevaseid tekste ja silte, kirjutan sõnumi ja kirja ning võrdlen tulemust lähtepunktiga.", "goals": {"g_read": "Õpilane valib igapäevases olukorras sobiva vastuse ja mõistab teateid trepikojas ja poes; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab kirjutades mooduli vorme: lihtminevik, osastav, ma- ja da-vorm, kohakäänded ja viisakas palve.", "g_use": "Õpilane kirjutab administraatorile sõnumi ja sõbrale kirja oma nädalast ning võrdleb tulemust tunni 1 lähtepunktiga."}, "tags": {}},
  "a2b1-006": {"canDo": "Ma kirjutan 30–60-sõnalise loo pildist oma perealbumist: kes on pildil ja kes nad mulle on (minu ema vend, õe tütar).", "goals": {"g_vocab": "Õpilane kasutab sugulussõnu: sugulane, suguvõsa, onu, tädi, nõbu, vanavanemad, lapselaps, põlvkond, abikaasa.", "g_read": "Õpilane saab aru tekstist „Üks pilt, kolm põlvkonda”: kes on kes ja kes on kellele sugulane, ning räägib sugupuu järgi.", "g_notice": "Õpilane moodustab omastava küsimusele kelle? (venna, õe, Igori, vanavanemate) ja kirjeldab sugulust: minu ema vend = onu.", "g_use": "Õpilane räägib ilma abita oma perest ja kirjutab 30–60-sõnalise loo pildist oma perealbumist; paariline küsib „Kelle …?”."}, "tags": {"006_d_cold": "g_vocab", "006_t_exit": "g_vocab", "006_d_text": "g_read", "006_d_read": "g_read", "006_d_tree": "g_read", "006_p_family": "g_notice", "006_p_sent": "g_notice", "006_t_story": "g_use", "006_t_home": "g_use"}},
  "a2b1-007": {"canDo": "Ma kirjeldan inimese välimust ja iseloomu kes-lausetega, lepin paarilisega kokku, keda soovitada, ja põhjendan oma valikut.", "goals": {"g_vocab": "Õpilane kasutab välimuse ja iseloomu sõnu: välimus, iseloom, habe, prillid, lokkis, kannatlik, rahulik, usaldama, igatsema, kartma.", "g_read": "Õpilane saab aru kuulutusest „Otsime lastele vanaema!”: millist inimest pere otsib ja miks.", "g_notice": "Õpilane ühendab laused kes-kõrvallausega (kes, kellel, keda, kellega) ja paneb kõrvallause ümber komad.", "g_use": "Õpilane kirjeldab inimest nii, et paariline ta pildilt ära tunneb, ja lepib kokku, keda perele soovitada."}, "tags": {"007_d_warm": "g_vocab", "007_t_exit": "g_vocab", "007_d_read": "g_read", "007_d_think": "g_read", "007_p_who": "g_notice", "007_p_sent": "g_notice", "007_t_choose": "g_use", "007_t_home": "g_use"}},
  "a2b1-008": {"canDo": "Ma helistan leitud asjade büroosse, kirjeldan oma kadunud asja mis-lausetega ja lepin kokku, kuidas ma selle kätte saan.", "goals": {"g_vocab": "Õpilane kasutab kaotamise ja leidmise sõnu: kaotama, leidma, unustama, kaduma, omanik, leitud asjad, sees, küljes, dokument.", "g_read": "Õpilane saab aru kohviku teatest „Leitud asjad”: mis on leitud, kus see on ja kuidas selle kätte saab.", "g_notice": "Õpilane eristab oma ja tema ning kirjeldab asja mis-lausega: kott, mille ma kaotasin; müts, millel on täht; asi, mis on laual.", "g_use": "Õpilane helistab büroosse, kirjeldab asja, reageerib ootamatule probleemile ja lepib kokku, millal ja kuidas asja kätte saab."}, "tags": {"008_d_warm": "g_vocab", "008_t_exit": "g_vocab", "008_d_found": "g_read", "008_d_think": "g_read", "008_p_call": "g_notice", "008_p_fix": "g_notice", "008_p_sent": "g_notice", "008_t_lost": "g_use", "008_t_home": "g_use"}},
  "a2b1-009": {"canDo": "Ma teen ettepaneku, põhjendan seda sest- või kuna-lausega, lepin pereliikmega peo plaani kokku ja kutsun häälsõnumiga päris inimese peole.", "goals": {"g_vocab": "Õpilane kasutab peo ja kokkuleppe sõnu: ettepanek, põhjus, kokku leppima, kokkulepe, kingitus, üllatus, külaline, kutse.", "g_read": "Õpilane saab aru häälsõnumist, kus tehakse peo kohta ettepanekuid ja põhjendatakse neid.", "g_notice": "Õpilane teeb ettepaneku (Teeme …! Võiksime …), põhjendab sest- või kuna-lausega ja sõnastab kokkuleppe: Lepime kokku, et …", "g_use": "Õpilane lepib pere nõupidamisel kokku peo plaani ja kutsub häälsõnumiga päris inimese peole."}, "tags": {"009_d_hook": "g_vocab", "009_t_exit": "g_vocab", "009_d_think": "g_read", "009_d_msg": "g_read", "009_p_why": "g_notice", "009_p_sent": "g_notice", "009_t_meet": "g_use", "009_t_invite": "g_use"}},
  "a2b1-010": {"canDo": "Ma saan aru pere teemalistest teadetest ja vestlustest, räägin ilma abita inimesest, kes on mulle tähtis, lepin kokku ja kirjutan lühikese sõnumi.", "goals": {"g_read": "Õpilane saab aru raadiovestlusest ja telefonisõnumist pere teemal; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: omastav, kes- ja mis-laused, oma, sest / kuna.", "g_use": "Õpilane räägib ilma abita inimesest, kes on talle tähtis, lepib kokku ja kirjutab sõnumi; võrdleb tulemust tunni 6 külma stardiga."}, "tags": {}},
  "a2b1-011": {"canDo": "Ma kirjeldan korterit liitega omadussõnadega, võrdlen kahte korterit ja kirjutan lähedasele 30–60-sõnalise sõnumi, kumma ma valin ja miks.", "goals": {"g_vocab": "Õpilane kasutab kodu ja üürimise sõnu: üürima, üür, omanik, korrus, ruumikas, valgusküllane, päikeseline, kodune, ohutu, ebamugav.", "g_read": "Õpilane saab aru kahest korterikuulutusest: milline korter on, mis on hea ja halb ning kumb sobib inimesele, ja räägib plaani järgi.", "g_notice": "Õpilane moodustab ja kasutab liitega omadussõnu: -ne / -line (kodune, päikeseline), -kas (ruumikas), -lik (rahulik), -tu (ohutu), eba- (ebamugav).", "g_use": "Õpilane räägib ilma abita oma kodust ja kirjutab lähedasele 30–60-sõnalise sõnumi, kumma korteri ta valib ja miks."}, "tags": {"011_d_cold": "g_vocab", "011_t_exit": "g_vocab", "011_d_open": "g_read", "011_d_read": "g_read", "011_d_plan": "g_read", "011_p_suffix": "g_notice", "011_p_sent": "g_notice", "011_t_mom": "g_use", "011_t_home": "g_use"}},
  "a2b1-012": {"canDo": "Ma saan aru häälsõnumist, kus asjad on ja kuhu need viia, lepin paarilisega kokku, kuhu mööbel läheb, ja kirjutan abilistele 30–60-sõnalise märkme.", "goals": {"g_vocab": "Õpilane kasutab kolimise sõnu: kolima, pakkima, kast, kandma, tõstma, kelder, aknalaud, riiul, kapp, abiline.", "g_read": "Õpilane saab aru häälsõnumist, kus asjad on, kust need võtta ja kuhu viia.", "g_notice": "Õpilane valib kus-, kuhu- ja kust-vormi (keldris – keldrisse – keldrist, voodi all – alla – alt, naabri juures – juurde – juurest) ja lühikese kuhu-vormi: tuppa, kööki, koju.", "g_use": "Õpilane lepib paarilisega kokku, kuhu mööbel läheb, kirjutab abilistele märkme ja leiab eesti.ee lehelt, kuidas elukohta registreerida."}, "tags": {"012_d_moves": "g_vocab", "012_t_exit": "g_vocab", "012_d_msg": "g_read", "012_d_where": "g_read", "012_p_markus": "g_notice", "012_p_sent": "g_notice", "012_t_note": "g_use", "012_t_home": "g_use"}},
  "a2b1-013": {"canDo": "Ma ütlen oma arvamuse linnaosa kohta, põhjendan seda sest- ja kuna-lausega ning lepin elanike koosolekul kokku, mida tühjale krundile teha.", "goals": {"g_vocab": "Õpilane kasutab linnaosa sõnu: linnaosa, elanik, krunt, mänguväljak, parkla, raamatukogu, koosolek, ettepanek, rahustav, puudu olema.", "g_read": "Õpilane saab aru elanike arvamustest raadios: kellele mis meeldib ja mis on puudu.", "g_notice": "Õpilane põhjendab arvamust sest- ja kuna-lausega (Kuna autosid on palju, ei ole tänav ohutu) ja kirjeldab kohta liitega omadussõnadega.", "g_use": "Õpilane ütleb koosolekul oma ettepaneku kahe põhjusega, vastab teise arvamusele ja lepib kokku ühe idee."}, "tags": {"013_d_opinion": "g_vocab", "013_t_exit": "g_vocab", "013_d_voices": "g_read", "013_d_think": "g_read", "013_p_why": "g_notice", "013_p_sent": "g_notice", "013_t_meeting": "g_use", "013_t_rec": "g_use"}},
  "a2b1-014": {"canDo": "Ma juhatan telefonis teed sõbrale (sina) ja võõrale (teie), küsin üle, kus inimene on, ja leian koos temaga õige tee.", "goals": {"g_vocab": "Õpilane kasutab tee juhatamise sõnu: ristmik, otse, pöörama, mööda, üle, läbi, maamärk, suletud, eksima, ümbersõit.", "g_read": "Õpilane saab aru kirjalikust teejuhisest: kuhu minna, kus pöörata ja mida mitte teha.", "g_notice": "Õpilane kasutab käskivat kõneviisi sõbrale ja võõrale (mine – minge, pööra – pöörake, ära mine – ärge minge) ja maamärke: kuni ristmikuni, mööda tänavat, üle tee, läbi pargi.", "g_use": "Õpilane juhatab telefonis eksinud külalist, küsib üle, kus ta on, ja lahendab ootamatu probleemi."}, "tags": {"014_d_first": "g_vocab", "014_t_exit": "g_vocab", "014_d_way": "g_read", "014_p_call": "g_read", "014_d_you": "g_notice", "014_p_sent": "g_notice", "014_t_call": "g_use", "014_t_home": "g_use"}},
  "a2b1-015": {"canDo": "Ma saan aru kodu ja linna teemalistest vestlustest ja sõnumitest, räägin ilma abita kohast, kus ma elan, lepin kokku ja kirjutan naabrile lühikese sõnumi.", "goals": {"g_read": "Õpilane saab aru raadiovestlusest ja telefonisõnumist kodu ja linna teemal; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: liitega omadussõnad, kus / kuhu / kust, sest / kuna, käskiv kõneviis.", "g_use": "Õpilane räägib ilma abita kohast, kus ta elab, lepib kokku ja kirjutab naabrile sõnumi; võrdleb tulemust tunni 11 külma stardiga."}, "tags": {}},
  "a2b1-016": {"canDo":"Ma räägin laagri päevakavast vähemalt kuue ajamäärusega ja lepin paarilisega kokku laupäeva kava.","goals":{"g_vocab":"Õpilane kasutab aja ja kava sõnu: kava, päevakava, kestma, veerand, kolmveerand, hiljemalt, vähemalt, öörahu, kui tihti.","g_read":"Õpilane leiab Kaie kirjast, häälsõnumist, Oskari päevikust ja vabatahtlike kaartidelt, mis toimub millal ja kui kaua.","g_notice":"Õpilane ütleb kellaaja (veerand, pool, kolmveerand), kestuse (kella üheksast kella kümneni) ning kasutab enne / pärast + osastavat ja kuni …-ni.","g_use":"Õpilane räägib oma päevast, küsib lahtiolekuaegu, lepib paarilisega kokku laagri päevakava ja vastab mures lapsevanemale."}},
  "a2b1-017": {"canDo":"Ma saan kuuldust aru, mida tööl peab, võib ja ei tohi teha, ja kirjutan sõbrale 80–100-sõnalise kirja tema uue töö reeglitest.","goals":{"g_vocab":"Õpilane kasutab reeglite sõnu: reegel, kohustus, luba, keelatud, lubatud, kandma, turvavest, ladu, lisatöötaja, ajutine.","g_read":"Õpilane saab aru lühiteadetest, Liisi juhendist, raadiointervjuust ja lasteaia häälsõnumist: mis on kohustus, luba või keeld.","g_listen":"Õpilane saab aru kuulamistekstidest „Kaheksa lühikest teadet”, „Liisi juhend lisatöötajatele”, „Raadio: telefonid koolis” ja „Lasteaia häälsõnum” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab peab / ei pea + ma-vormi ning võib, tohib, saab, ei tohi, on vaja + da-vormi ja eristab ei pea ja ei tohi.","g_use":"Õpilane kirjutab kolleegile lühiteate (Harno B1 kirjutamine 1), seletab sõbrale kuuldud reegleid ja kirjutab talle kirja."},"tags":{"017_d_clips":"g_listen","017_d_brief":"g_listen","017_p_radio":"g_listen","017_p_trip":"g_listen"}},
  "a2b1-018": {"canDo":"Ma loen kolleegi juhendist, mis tuleb ära teha ja mis võib oodata, ja kirjutan 80–100-sõnalise loo kahest päevast kolleegi asemel.","goals":{"g_vocab":"Õpilane kasutab ühendverbe ja töö sõnu: läbi lugema, ette valmistama, ära maksma, edasi lükkama, ära jääma, tähtaeg, aruanne, nimekiri.","g_read":"Õpilane mõistab Markuse lugu, ajakirja nõuandeid ja Anna kirja: mis on kiire, mis võib oodata ja mida pole vaja teha.","g_notice":"Õpilane paneb ühendverbi osakese õigesse kohta: Ma loen lepingu läbi; Ma ei loe lepingut läbi; Ma pean lepingu läbi lugema.","g_use":"Õpilane jutustab Markuse päevast, vastab ülemuse küsimustele tehtud tööde kohta ja kirjutab loo kahest päevast kolleegi asemel."}},
  "a2b1-019": {"canDo":"Ma helistan kliinikusse või bussifirmasse, lükkan aja edasi ja lepin kokku uue aja ning perega uue nädalavahetuse plaani.","goals":{"g_vocab":"Õpilane kasutab kokkuleppe sõnu: kokku leppima, kokkulepe, ümber tegema, sobima, kinnitama, kahjuks, ettepanek, keelduma.","g_read":"Õpilane mõistab häälsõnumitest, kuulutustest, siltidest ja artiklist, mis aeg muutus ja kuidas uut aega kokku leppida.","g_listen":"Õpilane saab aru kuulamistekstidest „Kaks häälsõnumit” ja „Kolm sõnumit laupäeva hommikul” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane teeb viisaka ettepaneku ja keeldub põhjusega (Kas teile sobiks…? Kahjuks ei saa, sest…) ning kasutab ühendverbe edasi lükkama, ära jääma, kokku leppima.","g_use":"Õpilane helistab kliinikusse ja bussifirmasse (Harno B1 rääkimine 2), lepib perega kokku uue plaani ja kirjutab kutse."},"tags":{"019_d_calls":"g_listen","019_t_news":"g_listen"}},
  "a2b1-020": {"canDo":"Ma sooritan vahehindamise Harno A2 vormis koos ühe B1 ülesandega igas osas ja võrdlen tulemust sisenemistestiga; eesmärk on vähemalt 80 % igas osas.","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 80 % punktidest, ka B1 vormis ülesannetes (kuulutused, artikkel, lühiteated, intervjuu).","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Liisi sõnum”, „Kellega klient räägib?” ja „Raadiointervjuu” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab õigesti moodulite 1–4 vorme: kohakäänded, lihtminevik, osastav, ma/da ja peab/võib, tingiv palve, omastav, ajamäärused, ühendverbid.","g_use":"Õpilane kirjutab teate ja kirja ning räägib endast, oma ajast ja plaanidest ja helistab asutusse; kirjutamises ja rääkimises vähemalt 80 %."},"tags":{"020_p_clips":"g_listen","020_p_party":"g_listen","020_p_who":"g_listen","020_p_radio":"g_listen"}},
  "a2b1-021": {"canDo":"Ma kirjutan haigele kolleegile 80–100-sõnalise kirja sellest, mis tööl juhtus, mida ma tegin ja mida ei teinud.","goals":{"g_vocab":"Õpilane kasutab tööpäeva tegusõnu minevikus: ärkasin, vastasin, kontrollisin, lõpetasin, saatsin, otsisin, muretsesin.","g_read":"Õpilane mõistab Markuse lugu, Anna päevikut, Markuse ja Sofia kõnet ning Liisi kirja: mis juhtus ja mis järjekorras.","g_listen":"Õpilane saab aru kuulamistekstidest „Kes oli ukse taga?” ja „Markuse teisipäev kella järgi” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane moodustab -si- ja -s-lihtmineviku kõigis isikutes (vastasin, ta vastas, ostsin) ja eituse: ei vastanud, ei ostnud.","g_use":"Õpilane jutustab loo kaks korda, räägib Liisile kohvipausil ja häälsõnumis nädala uudistest ning kirjutab talle 80–100-sõnalise kirja."},"tags":{"021_d_door":"g_listen","021_p_tuesday":"g_listen"}},
  "a2b1-022": {"canDo":"Ma räägin 2 minutit, mida ma eelmisel nädalavahetusel tegin, ja lepin kolleegiga kokku meeskonna laupäevase väljasõidu.","goals":{"g_vocab":"Õpilane kasutab mineviku ajasõnu ja nädalavahetuse tegevusi: üleeile, eelmisel nädalal, … tagasi, kõigepealt, pärast seda, lõpuks, puhkama, koristama.","g_read":"Õpilane mõistab Anna postitust, Viktori raadiokõnet, kolme nädalavahetuse lugu ja kolleegide kaarte: kes mida millal tegi.","g_listen":"Õpilane saab aru kuulamistekstidest „Raadio: Viktori imelik nädal” ja „Jaani jutt: numbrid” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane alustab lauset ajasõnaga ja paneb tegusõna teisele kohale (Laupäeval koristasin ma korteri) ning valib aja järgi mineviku, oleviku või tuleviku.","g_use":"Õpilane küsitleb teisi, räägib 4-3-2 korras oma nädalavahetusest, lepib kokku väljasõidu koha, broneerib selle telefonis ja kirjutab kutse."},"tags":{"022_d_radio":"g_listen","022_p_times":"g_listen"}},
  "a2b1-023": {"canDo":"Ma räägin festivali korraldajaga: kirjeldan erandlike minevikuvormidega, mis juhtus (tulin, nägin, sain), ja palun probleemile lahendust.","goals":{"g_vocab":"Õpilane kasutab festivali sõnu ja teeb tegusõnast inimese nimetuse: festival, vabatahtlik, järjekord, lava, auhind, müüja, esineja, külastaja.","g_read":"Õpilane saab aru lühikestest raadiouudistest (Harno B1 kuulamine 1), festivali teadetest, Jaani päevikust, korraldaja intervjuust ja häälsõnumist.","g_listen":"Õpilane saab aru kuulamistekstidest „Raadiouudised festivalilt”, „Intervjuu korraldajaga” ja „Merike häälsõnum” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane moodustab -i-lihtmineviku ja sagedased erandid (tuli, sõi, jõi, tõi, viis, sai, läks, tegi, nägi, pani) ning eituse: ei tulnud, ei läinud.","g_use":"Õpilane avaldab arvamust, tutvustab end vabatahtlikuna, kirjeldab korraldajale, mis juhtus, lepib kokku lahenduse, helistab piletiteenindusse ja vastab kirjale."},"tags":{"023_d_clips":"g_listen","023_p_interview":"g_listen","023_t_voice":"g_listen"}},
  "a2b1-024": {"canDo":"Ma kirjutan linnalehe võistlusele 80–100-sõnalise loo „Minu kõige ootamatum päev”: algus, probleem, mis edasi juhtus ja lõpp.","goals":{"g_vocab":"Õpilane kasutab loo sõnu: alguses, äkki, märkama, kaduma, mures, õnneks, kahjuks, tagasi saama, ootamatu, pealkiri.","g_read":"Õpilane leiab Anna raadioloost, eelmise aasta võidulugudest ja võistluse reeglitest loo osad, žürii nõuded ja vajaliku info.","g_notice":"Õpilane ühendab laused loo sõnadega (kõigepealt, siis, pärast seda, kui, sest, nii … et) ja paneb ajasõna järel tegusõna teisele kohale.","g_use":"Õpilane kirjutab piltide järgi kiirloo, plaanib ja parandab oma mustandi, täidab ankeedi, kirjutab võistlusele 80–100-sõnalise loo ja otsustab paarilisega nagu žürii."}},
  "a2b1-025": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis koos esimeste B1 ülesannetega ja saan igas osas vähemalt 80 % punktidest.","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 80 % punktidest, ka B1 ülesannetes (valiklünktekst, artikkel, lühikesed klipid).","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed klipid”, „Intervjuu võitjaga”, „Toimetaja sõnum” ja „Lugude õhtul” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab õigesti lihtmineviku -s-, -si- ja -i-vorme, erandeid, eitust ning ajasõna järel sõnajärge.","g_use":"Õpilane kirjutab sõnumi ja 70–90-sõnalise loo ning räägib minevikust ja telefonis; kirjutamises ja rääkimises vähemalt 80 %."},"tags":{"025_p_l1":"g_listen","025_p_l2":"g_listen","025_p_l3":"g_listen","025_p_l4":"g_listen"}},
  "a2b1-026": {"canDo":"Ma kirjutan Jaanile 80–100-sõnalise kirja pühapäevase lõuna menüüst ja ostunimekirjast koos kogustega.","goals":{"g_vocab":"Õpilane kasutab toidu ja koguse sõnu: toiduaine, kogus, nimekiri, pakk, purk, karp, liiter, köögivili, puuvili, värske.","g_read":"Õpilane mõistab Liisi blogist, turuvestlusest, poe raadioreklaamist ja kuulutustest, mida, kus ja kui palju osta.","g_listen":"Õpilane saab aru kuulamistekstidest „Laupäev Nõmme turul” ja „Poe raadioreklaam” (lüngad).","g_notice":"Õpilane kasutab koguse ja arvu järel osastavat: liiter piima, kilo kartuleid, kolm tomatit, natuke juustu.","g_use":"Õpilane lepib Jaaniga kokku pühapäevase lõuna menüü, seletab plaani Helgile ja kirjutab Jaanile 80–100-sõnalise kirja ostunimekirjaga."},"tags":{"026_d_market":"g_listen","026_p_radio":"g_listen"}},
  "a2b1-027": {"canDo":"Ma helistan restorani, broneerin laua kogu perele ning küsin toitude ja allergiate kohta.","goals":{"g_vocab":"Õpilane kasutab kohviku ja restorani sõnu: menüü, päevapraad, eelroog, pearoog, magustoit, ettekandja, arve, eraldi, broneerima, jootraha.","g_read":"Õpilane saab aru kohviku ja poe lühiteadetest, tellimisest Kaneelis, raadiointervjuust ja restorani häälsõnumist.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Lõuna Kaneelis”, „Raadiointervjuu: kohviku omanik” ja „Restorani häälsõnum” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane tellib ja palub viisakalt (Palun mulle…, Ma sooviksin…, Kas saaksime…?) ja kasutab -ks vormi: supiks, joogiks, magustoiduks.","g_use":"Õpilane tellib kohvikus allergiat arvestades, helistab restorani laua broneerimiseks ja kirjutab perele sõnumi."},"tags":{"027_d_clips":"g_listen","027_d_lunch":"g_listen","027_p_radio":"g_listen","027_t_voice":"g_listen"}},
  "a2b1-028": {"canDo":"Ma kirjutan 8–10-lauselise loo sellest, mis juhtus Markuse lõunaga, ja kasutan õigesti täis- ja osasihitist (sõi supi ära, ei söönud leiba).","goals":{"g_vocab":"Õpilane kasutab köögi sõnu: retsept, kaste, keetma, lõikama, maitsma, valmis, ära sööma, nõud, karp, reegel.","g_read":"Õpilane mõistab Sofia päevikut, Anna häälsõnumit retseptiga, raadiolugu toidu raiskamisest ja Markuse sõnumit: mis on tehtud ja mis jäi pooleli.","g_notice":"Õpilane eristab osastavat ja täissihitist: söön leiba – sõin leiva ära, tegi salati valmis; eituses on alati osastav: ei ostnud leiba.","g_use":"Õpilane jutustab, mis juhtus Markuse lõunaga, lepib köögikoosolekul kokku viis reeglit ja kirjutab sellest 8–10-lauselise loo."}},
  "a2b1-029": {"canDo":"Ma helistan toidukulleri klienditeenindusse, kirjeldan probleemi viisakalt ja nõuan lahendust, mis tingimuste järgi mulle kuulub.","goals":{"g_vocab":"Õpilane kasutab kaebuse sõnu: probleem, viga, kaebus, lahendus, vahetama, nõudma, allahindlus, hilinema, tellimus, kuller.","g_read":"Õpilane mõistab kohvikuvestlust, teateid, arvustusi ning tellimuse kinnitust ja tingimusi: mis läks valesti ja mida võib nõuda.","g_notice":"Õpilane kaebab nelja sammuga (pöördumine, probleem, palve, tänu) ja ühendab laused sõnadega aga, sest, kuna, et, vaid.","g_use":"Õpilane lahendab kohvikus vale tellimuse, helistab klienditeenindusse ja nõuab lahendust ning kirjutab firmale 80–100-sõnalise vastuse."}},
  "a2b1-030": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis koos B1 ülesannetega: loen, kuulan, kirjutan ja räägin toidu ja teeninduse teemal; eesmärk on vähemalt 80 % igas osas.","goals":{"g_vocab":"Õpilane kasutab mooduli 6 toidu, koguse, teeninduse ja kaebuse sõnu ilma toeta.","g_read":"Õpilane saab lugemises ja kuulamises vähemalt 80 % punktidest (A2 ülesanded ja B1 ülesanded R1, R2, R3a, L1, L3a, L4).","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Telefonisõnum”, „Intervjuu turul” ja „Pikniku plaan” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab õigesti osastavat koguse ja eituse järel ning täissihitist lõpetatud tegevuse puhul.","g_use":"Õpilane saab kirjutamises (W1b, W2a) ja rääkimises (S0, S1a, S2) vähemalt 80 % punktidest."},"tags":{"030_p_l1":"g_listen","030_p_l2":"g_listen","030_p_l3":"g_listen","030_p_l4":"g_listen"}},
  "a2b1-031": {"canDo":"Ma kirjutan haigeks jäänud kolleegile 80–100-sõnalise kirja: mis tööl juhtus, mida ma tema eest tegin ja mida ma soovitan.","goals":{"g_vocab":"Õpilane kasutab haiguse sõnu: haige, terve, palavik, köha, nohu, kurk, valutama, väsinud, puhkama, paranema, apteek.","g_read":"Õpilane saab aru Anna ja Sofia vestlusest, lastearsti kirjutisest, raadiosaatest gripi kohta ja Anna häälsõnumist: mis juhtus ja mida tuleb teha.","g_listen":"Õpilane saab aru kuulamistekstidest „Esmaspäev kontoris”, Raadio „Päevateema ja „Anna häälsõnum” (lüngad).","g_notice":"Õpilane eristab olekut ja muutust: olen haige – jäin haigeks, sain terveks, palavik läks kõrgeks (omastav + -ks).","g_use":"Õpilane kirjeldab haiget inimest, ütleb oma arvamuse, kirjutab ülemusele sõnumi, lepib kokku tööde jagamise ja kirjutab haigele kolleegile kirja."},"tags":{"031_d_office":"g_listen","031_p_radio":"g_listen","031_t_voice":"g_listen"}},
  "a2b1-032": {"canDo":"Ma helistan Markuse eest perearstikeskusse, räägin, kuidas tema haigus on muutunud, ja broneerin talle sobiva aja.","goals":{"g_vocab":"Õpilane kasutab arsti ja apteegi sõnu: arst, perearst, hääl, kestma, tõsine, hingama, ravim, retsept, tablett, aeg; mõistab ravimi infolehte.","g_read":"Õpilane mõistab Markuse lugu, vestlust perearsti juures, teateid selle kohta, kuhu pöörduda, ja Markuse sõnumit.","g_notice":"Õpilane kasutab muutuse tegusõnu saava käändega: jäi kähedaks, läks hullemaks, muutus tugevamaks, sai terveks.","g_use":"Õpilane jutustab Markuse loo, kirjutab kliendile ametliku kirja, helistab tema eest perearstikeskusse, järjestab tööd ja kirjutab kaardi."}},
  "a2b1-033": {"canDo":"Ma lepin Markusega kokku kahenädalase uneplaani ja annan talle suuliselt nõu käskiva kõneviisiga (pane telefon ära, ära joo õhtul kohvi).","goals":{"g_vocab":"Õpilane kasutab vigastuse, une ja enesetunde sõnu: põlv, jalg, valu, kukkuma, harjutus, ettevaatlik, uni, voodi, rahulik, enesetunne, meeleolu, muretsema, pöörduma.","g_read":"Õpilane saab aru arsti, apteekri ja füsioterapeudi juhistest, lühikestest teadetest ja Markuse unepäevikust.","g_listen":"Õpilane saab aru kuulamistekstidest „Traumapunktis” ja „Perearstikeskuse automaatvastaja” (lüngad).","g_notice":"Õpilane moodustab käsu ja keelu sinale ja teile: pane – pange, võta – võtke, ära sõida – ärge sõitke.","g_use":"Õpilane annab Viktorile nõu, lahendab apteegis probleemi, vastab teemaküsimustele, lepib Markusega kokku uneplaani, kirjutab talle vastuse ja soovitab vajaduse korral abi otsida."},"tags":{"033_d_doctor":"g_listen","033_p_phone":"g_listen"}},
  "a2b1-034": {"canDo":"Ma kirjutan kontori infolehte 80–100-sõnalise jutu sellest, kuidas mu harjumused kuu ajaga muutusid.","goals":{"g_vocab":"Õpilane kasutab harjumuste ja spordi sõnu: harjumus, tervislik, liikuma, kõndima, jalgsi, eesmärk, tulemus, õnnestuma, loobuma, dieet, kaal, vorm, rämpstoit, treenima, jõusaal, võistlema.","g_read":"Õpilane mõistab Liisi kutset, Jaani lugu, infolehe lugu sportlastest, raadiointervjuud harjumustest ja osalejate tulemusi, leiab lõikudele pealkirja ja parandab valed väited.","g_notice":"Õpilane ehitab jutu üles (probleem, esimene samm, raske hetk, tulemus, soovitus), ühendab laused sidesõnadega ja kasutab muutuse vormi.","g_use":"Õpilane küsitleb teisi ja põhjendab vastuseid, täidab küsimustiku, vaidleb uue kolleegiga ja kirjutab infolehte 80–100-sõnalise jutu ning selle parema versiooni."}},
  "a2b1-035": {"canDo":"Ma sooritan mooduli eksami Harno A2 vormis koos B1 ülesannetega: loen, kuulan, kirjutan ja räägin tervise teemal; eesmärk on vähemalt 80 % igas osas.","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 80 % punktidest (A2 ülesanded ja B1 ülesanded R1, R2, R3a, L1, L3a, L4).","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Treeneri sõnum”, „Intervjuu õega” ja „Oskar ja ema” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab õigesti muutuse vormi (jäi haigeks, läks paremaks) ning käsku ja keeldu sinale ja teile.","g_use":"Õpilane saab kirjutamises (W1a, W2a) ja rääkimises (S0, S1a, S2) vähemalt 80 % punktidest."},"tags":{"035_p_l1":"g_listen","035_p_l2":"g_listen","035_p_l3":"g_listen","035_p_l4":"g_listen"}},
  "a2b1-036": {"canDo":"Ma helistan kooli huvijuhile, räägin, millest laps huvitub ja milles ta osaleda tahab, ning küsin huviringide kohta.","goals":{"g_vocab":"Õpilane kasutab kooli ja huviringide sõnu: klassijuhataja, õppeaine, hinne, ring, trenn, registreerima ning tegusõnu osalema, harjuma, valmistuma.","g_read":"Õpilane saab aru klassijuhataja kirjast, koolilehe intervjuust (Harno B1 lugemine 2), Olena ja Sofia vestlusest ning huviringide kaartidest.","g_notice":"Õpilane kasutab tegusõna rektsiooni ja kaassõnu: huvitub millest?, osaleb milles?, harjub millega?, valmistub milleks?, palub abi kellelt?, muret kelle pärast?","g_use":"Õpilane lepib kokku lapse huviringid, helistab huvijuhile, kirjutab klassijuhatajale sõnumi ja tutvustab end lastevanemate õhtul."}},
  "a2b1-037": {"canDo":"Ma kirjutan sõbrale 80–100-sõnalise kirja oma õppimisplaanist ja kasutan pärast tegusõnu õiget vormi: pean õppima, tahan osata.","goals":{"g_vocab":"Õpilane kasutab õppimise ja eksami sõnu: eksam, eesmärk, sooritama, tase, sõnavara, grammatika, test, tunnistus.","g_read":"Õpilane saab aru raadiosaatest (Harno B1 kuulamine 2), Anna ja Liisi lõunavestlusest, kontori infotahvlist ja keelekooli häälsõnumist.","g_listen":"Õpilane saab aru kuulamistekstidest „Raadiosaade”, „Lõuna Liisiga” ja „Administraatori häälsõnum” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane valib pean, hakkan, lähen, jään järel ma-vormi ning tahan, oskan, saan, proovin, on vaja järel da-vormi.","g_use":"Õpilane kirjutab kutse lõunaklubisse, seletab häälsõnumi sisu juhile, räägib oma õppimisplaanist ja kirjutab sõbrale kirja."},"tags":{"037_d_radio":"g_listen","037_d_lunch":"g_listen","037_t_voice":"g_listen"}},
  "a2b1-038": {"canDo":"Ma kirjutan umbes 100-sõnalise jutu sellest, miks ma õpin, ja põhjendan oma valikuid sõnadega sest, kuna ja seepärast.","goals":{"g_vocab":"Õpilane kasutab põhjuse ja õppimisharjumuste sõnu: põhjus, tagajärg, väsinud, uni, harjumus, keskenduma, kasulik, vajalik ning -mine-nimisõnu.","g_read":"Õpilane leiab ajakirja loost, küsitluse diagrammist, keelekooli uudiskirjast ja Anna blogist põhjused ja tagajärjed.","g_listen":"Õpilane saab aru kuulamistekstidest „Kohviautomaadi juures” ja „Koolijuhi häälsõnum” (küsimused kuuldu kohta).","g_notice":"Õpilane eristab põhjust ja tagajärge ning sõnajärge: Kuna päeval pole aega, õpib Anna õhtul; …, seepärast oli ta väsinud.","g_use":"Õpilane täidab küsimustiku põhjendustega (Harno B1 kirjutamine 1), lepib juhiga kokku tööaja ja kirjutab jutu „Miks ma õpin”."},"tags":{"038_d_coffee":"g_listen","038_p_director":"g_listen"}},
  "a2b1-039": {"canDo":"Ma räägin oma õppimismurest ja lepin kokku lahenduse: millise kursuse või abi ma valin ja kuidas edasi õpin.","goals":{"g_vocab":"Õpilane kasutab õpimure sõnu: mure, lahendus, maha jääma, järele jõudma, puuduma, julgema, seletama, individuaalne, konsultatsioon.","g_read":"Õpilane saab aru häälsõnumitest, õpetaja nõuannetest, kursuste kuulutustest ja pakkumiste tabelist ning leiab neist sobiva lahenduse.","g_listen":"Õpilane saab aru kuulamistekstidest „Kümme häälsõnumit” ja „Õpetaja Hanna sõnum Markusele” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab rektsiooni (puudus millest, keskendub millele, palub abi kellelt) ja viisakat palvet: Kas te saaksite…? Kas ma võiksin…?","g_use":"Õpilane räägib oma õppimismurest, helistab keelekooli (Harno B1 rääkimine 2), lepib kokku õppimisplaani ja vastab õpetaja kirjale."},"tags":{"039_d_worries":"g_listen","039_d_teacher":"g_listen"}},
  "a2b1-040": {"canDo":"Ma sooritan vahehindamise Harno A2 vormis koos B1 lugemis- ja kuulamisülesannetega ning kirjutan ja räägin B1 vormis; eesmärk on vähemalt 80 % igas osas ja võrdlus tundidega 1 ja 20.","goals":{"g_read":"Õpilane saab lugemises ja kuulamises vähemalt 80 % punktidest (A2 ülesanded ja B1 ülesanded R1, R2, R3a, L1, L2, L3a).","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed teated”, „Raadiolugu” ja „Telefonikõne” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab õigesti mooduli 8 sõnavara, rektsiooni ja kaassõnu, ma- ja da-vormi, sest- ja kuna-lauset ning varasemate moodulite vorme.","g_use":"Õpilane saab kirjutamises (W1b, W2a) ja rääkimises (S0, S1a, S2) vähemalt 80 % punktidest ja võrdleb oma profiili tundidega 1 ja 20."},"tags":{"040_p_l1":"g_listen","040_p_l2":"g_listen","040_p_l3":"g_listen","040_p_l4":"g_listen"}},
  "a2b1-041": {"canDo":"Ma kirjutan 90–110-sõnalise jätkuloo „Jaani otsus”: kellena Jaan töötab, mille eest ta vastutab ja mis edasi juhtub.","goals":{"g_vocab":"Õpilane kasutab ametite ja töö sõnu: amet, töökoht, vastutama, tegelema, hoolitsema, vahetus, palk, tööaeg, kuulutus, ülemus, ning tegija nimesid lõpuga -ja (müüja, tööandja).","g_read":"Õpilane mõistab Jaani lugu, Kadri raadiointervjuud ja Kadri kirja: kes kellena töötab, mille eest vastutab ja miks Jaan mõtleb töökoha vahetamisele; lahendab valiklünkteksti (Harno lugemine 3).","g_listen":"Õpilane saab aru kuulamistekstidest Raadio: „Minu amet ja „Jaani pikk laupäev” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab -na-vormi (töötab kokana), vastutama/hoolitsema + omastav + eest ja tegelema + -ga ning valib valiklüngas vormi lause mõtte järgi.","g_use":"Õpilane kirjeldab ameteid pildil, arutab töökoha vahetamise poolt- ja vastuargumente ning kirjutab 90–110-sõnalise jätkuloo „Jaani otsus”."},"tags":{"041_d_radio":"g_listen","041_p_day":"g_listen"}},
  "a2b1-042": {"canDo":"Ma vastan kontori telefonile ja räägin helistajaga 2–3 minutit: ütlen ma-vormidega, kus kolleeg on ja millal ta tagasi tuleb (on kliendiga kohtumas, tuleb söömast), ja võtan sõnumi vastu.","goals":{"g_vocab":"Õpilane kasutab kontori ja telefoni sõnu: vastuvõtt, koosolek, koolitus, ladu, klient, tellimus, hinnapakkumine, sõnum, tagasi helistama, lõunapaus.","g_read":"Õpilane mõistab Sofia telefonikõnesid, raadiosaadet kodus töötamisest (Harno kuulamine 2), kontori nädalatahvlit ja kõneposti sõnumeid: kes on kus ja mida tuleb teha.","g_listen":"Õpilane saab aru kuulamistekstidest „Telefon heliseb”, Raadiosaade „Kodus või kontoris? ja „Hommikused sõnumid” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane eristab ma-vormi käändeid: läks kontrollima (kuhu), on kohtumas (kus), tuli söömast (kust), jäi saatmata (ilma); käib … -mas.","g_use":"Õpilane vastab kontori telefonile 2–3 minutit, ütleb tahvli järgi, kus kolleeg on, võtab sõnumi vastu ning kirjutab kutse ja teate."},"tags":{"042_d_calls":"g_listen","042_p_radio":"g_listen","042_t_voice":"g_listen"}},
  "a2b1-043": {"canDo":"Ma kirjutan töökuulutusele 90–110-sõnalise kandideerimiskirja: kes ma olen, mida oskan, miks see töö mulle sobib ja millal saan alustada.","goals":{"g_vocab":"Õpilane kasutab kandideerimise sõnu: kandideerima, kandidaat, kogemus, oskus, haridus, soovitus, tööandja, sobima, alustama, katseaeg, lugupidamisega.","g_read":"Õpilane mõistab raadio töökuulutuse numbreid, Anna kandideerimiskirja ülesehitust, karjäärinõustaja artiklit ja nelja töökuulutust.","g_notice":"Õpilane valib ma- või da-vormi tööväljendites (olen harjunud töötama, oskan teha, käisin õppimas), ühendab laused sidesõnadega ja kirjutab ametlikus registris.","g_use":"Õpilane täidab kandideerimisankeedi (Harno kirjutamine 1), lepib kokku, kes kuhu kandideerib, kirjutab 90–110-sõnalise kandideerimiskirja ja parandab selle hindamisjuhendi järgi."}},
  "a2b1-044": {"canDo":"Ma räägin töövestlusel oma kogemusest ja oskustest, toon iga tugevuse kohta näite, esitan ise kaks küsimust ja lepin kokku, millal tööd alustan.","goals":{"g_vocab":"Õpilane kasutab töövestluse sõnu: tugevus, nõrkus, näide, meeskond, täpne, paindlik, juhendaja, kutse, kokkulepe, lahkuma.","g_read":"Õpilane mõistab kutset töövestlusele, Merike vastust, Anna töövestluse salvestust, nõuandeid ja direktori häälsõnumit: mida küsitakse ja mis on Jaani probleem.","g_listen":"Õpilane saab aru kuulamistekstidest „Anna vestlus aasta tagasi” ja „Maire kõne” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane ehitab vastuse väide + näide + seos ja kasutab ma-vorme (olen harjunud töötama, käisin kursusel õppimas, ükski tellimus ei jäänud täitmata); parandab tüüpvead.","g_use":"Õpilane vastab töövestluse küsimustele 3–4 lausega, lepib ideekaardi abil kokku (Harno rääkimine 1), teeb telefonivestluse ja leiab endise ülemusega kompromissi."},"tags":{"044_d_anna":"g_listen","044_t_voice":"g_listen"}},
  "a2b1-045": {"canDo":"Ma sooritan mooduli eksami Harno B1 vormis (lühendatud): kirjutan, loen, kuulan ja räägin töö teemal ning saan igas osas vähemalt 80 % punktidest.","goals":{"g_read":"Õpilane saab lugemises (R1–R4) ja kuulamises (L1–L4) vähemalt 80 % punktidest: töökuulutused, artikkel, valiklünktekst, fraasid tekstis, teated, raadiolugu, vestlus ja intervjuu.","g_listen":"Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Vestlus” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).","g_notice":"Õpilane kasutab õigesti -na-vormi, vastutama … eest, tegelema …-ga, ma-vormi käändeid ning ma- ja da-vormi tööväljendites.","g_use":"Õpilane saab kirjutamises (teade W1b, jutt W2a) ja rääkimises (S0, S1a, S1b, S2) vähemalt 80 % punktidest."},"tags":{"045_t_l1":"g_listen","045_t_l2":"g_listen","045_t_l3":"g_listen","045_t_l4":"g_listen"}},
  "a2b1-046": {"canDo": "Ma helistan rongifirma infotelefonile, vahetan pere piletid ja selgitan onule telefonis tema teekonna ümberistumisega.", "goals": {"g_vocab": "Õpilane kasutab rongireisi sõnu: rong, pilet, jaam, väljuma, saabuma, ümber istuma, vagun, istekoht, sõiduplaan, edasi-tagasi, hilinema, reisija.", "g_read": "Õpilane saab aru Sofia ja Jaani kõnest, rongisaatja raadiointervjuust, jaama teadetest ja teadaannetest ning Viktori häälsõnumist: ajad, hinnad, perroonid ja reeglid.", "g_listen": "Õpilane saab aru kuulamistekstidest „Sofia ja Jaan valivad rongi”, „Rongisaatja raadios” ja „Teadaanded Balti jaamas” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab sõiduinfos kohavorme: väljub Tallinnast / Tapalt, saabub Tartusse / Tapale, istub ümber Tapal, ootab ooteruumis.", "g_use": "Õpilane vahetab telefonis rongipiletid, lahendab rongisaatjaga kohtade probleemi, selgitab onule teekonda ja kirjutab emale 50–70-sõnalise sõnumi."}, "tags": {"046_d_call": "g_listen", "046_d_radio": "g_listen", "046_p_announce": "g_listen"}},
  "a2b1-047": {"canDo": "Ma loen reisipakkumisi ja ülemuse kirja, võrdlen võimalusi ja kirjutan ülemusele 80–100-sõnalise vastuse reisiplaani ja kuludega.", "goals": {"g_vocab": "Õpilane kasutab reisi planeerimise sõnu: töölähetus, näitus, eelarve, lend, lennujaam, broneerima, hotell, hommikusöök, soodne, mugav, võrdlema, kulu.", "g_read": "Õpilane leiab reisiblogist, kuulutustest, näituse infost ja Liisi kirjast hinnad, ajad ja tingimused ning saab aru hotelli telefonikõnest.", "g_notice": "Õpilane võrdleb ja põhjendab: eelistan bussi lennukile, kumb on parem, mõlemad, kumbki, pigem … kui, seepärast; esitab hotellile viisakaid küsimusi.", "g_use": "Õpilane lepib Markusega plaani kokku, kaitseb seda Liisi ees ja kirjutab Liisile 80–100-sõnalise vastuse plaani ja kuludega."}},
  "a2b1-048": {"canDo": "Ma räägin reisiloo õiges järjekorras, ütlen enneminevikus, mis oli enne juhtunud (laev oli juba lahkunud), ja lepin žüriis kokku parima loo.", "goals": {"g_vocab": "Õpilane kasutab reisiloo sõnu: sadam, laev, lahkuma, jõudma, märkama, unustama, selguma, kinnitama, õnneks, kahjuks, lõpuks, meenutama.", "g_read": "Õpilane mõistab Anna blogist, raadiosaatest „Teel juhtunud” ja kuulajate lugudest, mis juhtus enne ja mis pärast.", "g_notice": "Õpilane moodustab enneminevikku (oli lahkunud, olime unustanud, polnud kinnitanud) ja eristab seda lihtminevikust ja täisminevikust.", "g_use": "Õpilane jutustab oma reisiloo kaks korda, vastab reisimise teemaküsimustele, lepib žüriis kokku parima loo ja kirjutab saate kodulehele umbes 100-sõnalise jutu."}},
  "a2b1-049": {"canDo": "Ma kirjutan sõbrale 80–100-sõnalise kirja tema reisi plaaniga: sõidud, ööbimine, hinnad ja üks hea nõuanne.", "goals": {"g_vocab": "Õpilane kasutab reisi korraldamise sõnu: ühendus, peatus, bussijaam, ööbima, külalistemaja, vaatamisväärsus, kohver, pagas, tühistama, viimane, piisama, soovitus.", "g_read": "Õpilane mõistab Lena häälsõnumit, Markuse lugu Viljandist, linnade tutvustust, Sofia ja Lena sõnumeid ning sõiduplaani ja hinnakirja.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lena häälsõnum” ja „Markuse lugu Viljandist” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab enneminevikku põhjuses ja hoiatuses: Ma ei teadnud, et buss oli juba läinud; Kui me jõudsime, oli … juba …; sest öösel oli lund sadanud.", "g_use": "Õpilane helistab külalistemajja, lepib Lenaga plaani kokku ja kirjutab Lenale 80–100-sõnalise isikliku kirja reisiplaaniga."}, "tags": {"049_d_lena": "g_listen", "049_d_markus": "g_listen"}},
  "a2b1-050": {"canDo": "Ma sooritan reisiteemalise mooduli eksami Harno B1 vormis lühendatud pikkusega: loen, kuulan, kirjutan ja räägin ajapiiranguga; eesmärk on vähemalt 80 % igas osas.", "goals": {"g_read": "Õpilane saab lugemises (28 punkti) ja kuulamises (23 punkti) vähemalt 80 % punktidest.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Telefonikõne” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti kohavorme sõiduinfos, enneminevikku ja valiku põhjendamise sõnu (eelistan bussile, kumb, mõlemad).", "g_use": "Õpilane saab kirjutamises (20 punkti) ja rääkimises (20 punkti) vähemalt 80 % punktidest."}, "tags": {"050_p_l1": "g_listen", "050_p_l2": "g_listen", "050_p_l3": "g_listen", "050_p_l4": "g_listen"}},
  "a2b1-051": {"canDo": "Ma loen poe pakkumisi, võrdlen hindu ja lepin poes kokku, mida eelarve piires osta.", "goals": {"g_vocab": "Õpilane kasutab ostlemise sõnu: hind, soodustus, pakkumine, garantii, kehtima, tšekk, müüja, sularaha, kokku, eelarve, tagastama, proovima.", "g_read": "Õpilane loeb teema avalehte raha ja ostlemise kohta Eestis, poe Nutikas pakkumisi, soodusmüügi artiklit ja allahindluse reeglit ning spordipoe saabaste kaarte ning saab aru Sofia jutust ja kaubanduskeskuse teadetest.", "g_listen": "Õpilane saab aru kuulamistekstidest „Kuidas Sofia telefon kadus” ja „Teadaanded kaubanduskeskuses” (küsimused kuuldu kohta).", "g_notice": "Õpilane küsib poes hinda, soodustust ja varianti (Kas seda on ka suuruses 34? Kas sellele on soodustust?) ja arvutab protsendi: 20 % odavam.", "g_use": "Õpilane leiab infolüngaga soodsama poe, lepib Oskariga 60 euro piires saabaste valiku kokku, arutleb laste hobide kulude üle ja kirjutab Kadrile 60–80-sõnalise sõnumi."}, "tags": {"051_d_lost": "g_listen", "051_p_mall": "g_listen"}},
  "a2b1-052": {"canDo": "Ma kirjutan Helgile 80–100-sõnalise kirja, milles võrdlen kaht autot ja põhjendan, miks pere ühe valis.", "goals": {"g_vocab": "Õpilane kasutab autoostu sõnu ja sidesõnu: kasutatud, kuulutus, kütus, pagasiruum, mugav, soodne, võrdlema, proovisõit, kauplema, otsustama, kindlustus, leping; sest, kuigi, seepärast.", "g_read": "Õpilane loeb Kadri kirja, auto- ja rattakuulutusi, kasutatud auto ostja meelespead (Transpordiamet, liikluskindlustus, automaks) ning Karini e-kirja ja saab aru Jaani kõnest müüjaga: hinnad, aastad ja tingimused.", "g_notice": "Õpilane moodustab kesk- ja ülivõrde (odavam, väiksem, parem, rohkem, kõige parem), võrdleb kahel viisil (odavam kui Škoda = Škodast odavam) ja seob laused sidesõnadega.", "g_use": "Õpilane kirjutab müüjale viisaka sõnumi, täidab autoportaali küsimustiku, kaupleb müüjaga hinna üle ja kirjutab Helgile 80–100-sõnalise kirja auto valikust."}},
  "a2b1-053": {"canDo": "Ma kirjutan e-poele 80–100-sõnalise kaebuse: mida tellisin, mis juhtus ja mida soovin, ning kasutan kesksõnu (tellitud jope, makstud raha).", "goals": {"g_vocab": "Õpilane kasutab tagastamise sõnu: katkine, parandama, remont, vahetama, karp, laadija, tellimus, kaebus, asendama, tasuta, teenindus, kasutamata.", "g_read": "Õpilane saab aru raadiosaate „Tarbija tund” nõuannetest ja e-poe Lasteriie selgitustest ning loeb poe tagastamise ja garantii tingimusi ja e-poest taganemise õigust (14 päeva).", "g_notice": "Õpilane kasutab kesksõnu nimisõna ees: ostetud kaup, makstud arve, avatud pakend, parandatud telefon, kehtiv garantii, soovitatav hind.", "g_use": "Õpilane seletab sõbrale, mida teeninduses öeldi, lahendab teeninduslauas kõrvaklappide probleemi, helistab e-poodi ja kirjutab poele 80–100-sõnalise kaebuse."}},
  "a2b1-054": {"canDo": "Ma selgitan, kuidas Eestis e-teenustes ja e-poes turvaliselt oma isikut tõendada ja maksta, ning helistan poe juhatajale garantiiprobleemi pärast ja põhjendan oma nõuet.", "goals": {"g_vocab": "Õpilane kasutab kaebuse sõnu: nõue, nõudma, juhataja, tõend, niiskus, lahendus, rahul, soovitama, arvustus, õigus, vastama, tähtaeg.", "g_read": "Õpilane loeb foorumi arutelu ID-kaardi, Mobiil-ID ja Smart-ID kohta, teab, kuidas pangalingi ja viipemaksega turvaliselt maksta ja mis on kahe aasta nõudeõigus, saab aru töökoja häälsõnumist ja raadio tarbijanõustaja nõuannetest ning loeb poe teateid, remondiakte ja garantiitingimusi.", "g_listen": "Õpilane saab aru kuulamistekstidest „Töökoja häälsõnum” ja „Raadio: kuidas kaevata nii, et see aitab?” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab kaebuses kesksõnu (parandatud telefon, makstud summa, täidetud leht) ja viisakat, kuid kindlat teie-käsku: parandage, vastake, saatke, ärge võtke.", "g_use": "Õpilane küsitleb teisi maksmise ja e-teenuste kohta, valib järgmise sammu, täidab garantiinõude vormi, räägib poe juhatajaga telefonis, salvestab kokkuvõtte ja kirjutab poe kodulehele arvustuse."}, "tags": {"054_d_voice": "g_listen", "054_p_radio": "g_listen"}},
  "a2b1-055": {"canDo": "Ma sooritan raha, ostlemise ja teenuste mooduli eksami Harno B1 vormis täispikkuses: loen, kuulan, kirjutan ja räägin ajapiiranguga; eesmärk on vähemalt 80 % igas osas.", "goals": {"g_vocab": "Õpilane tunneb mooduli sõnu poe, panga, töökoja ja e-poe kohta: soodustus, garantii, tšekk, kauplema, tagastama, tellimus, kaebus, tõend, arvustus.", "g_read": "Õpilane saab lugemises (33 punkti) ja kuulamises (30 punkti) vähemalt 80 % punktidest.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Telefonikõne” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti võrdlust, kesksõnu nimisõna ees ja viisakat teie-käsku.", "g_use": "Õpilane saab kirjutamises (20 punkti) ja rääkimises (20 punkti) vähemalt 80 % punktidest."}, "tags": {"055_p_l1": "g_listen", "055_p_l2": "g_listen", "055_p_l3": "g_listen", "055_p_l4": "g_listen"}},
  "a2b1-056": {"canDo": "Ma kuulan raadio ilmateadet ja kirjutan pere vestlusesse 50–70-sõnalise teate, millal me ilma tõttu matkale läheme ja miks.", "goals": {"g_vocab": "Õpilane kasutab ilma ja aastaaegade sõnu: ilmateade, palav, jahe, äike, välk, hoovihm, tuul, puhang, kraad, tuleoht, hoiatus, muutuma.", "g_read": "Õpilane saab aru raadio ilmateatest ja päästja raadiointervjuust: kraadid, kellaajad, tuule kiirus, hoiatused ja nõuanded.", "g_notice": "Õpilane ütleb, kuidas ilm muutub (läheb jahedamaks, muutub tuuliseks, tõuseb kahekümne kraadini) ja kasutab ilmateate vorme oodatakse, soovitatakse.", "g_use": "Õpilane arutab ilmaäpi põhjal matka aega, leiab kompromissi ja kirjutab pere vestlusesse otsuse koos põhjusega."}, "tags": {"056_d_notes": "g_vocab", "056_d_colleague": "g_vocab", "056_d_radio": "g_read", "056_p_radio": "g_read", "056_p_notes": "g_notice", "056_p_reply": "g_notice", "056_t_talk": "g_use", "056_t_message": "g_use"}},
  "a2b1-057": {"canDo": "Ma loen lühikesi tekste rabast, jutustan kui-lausetega, mis juhtus, ja kirjutan küla gruppi 70–90-sõnalise postituse, kuidas Muki kadus.", "goals": {"g_vocab": "Õpilane kasutab looduse ja äikese sõnu: raba, laudtee, vaatetorn, turvas, sammal, müristama, kiirustama, kukkuma, märg, kaduma, otsima.", "g_read": "Õpilane loeb populaarteaduslikku teksti rabast ja matkaraja teateid ning leiab neist vajaliku info.", "g_notice": "Õpilane jutustab kui-, enne kui-, pärast seda, kui- ja samal ajal kui -lausetega (pealauses tegusõna kohe) ning kasutab lihtminevikku ja enneminevikku.", "g_use": "Õpilane lepib naabriga kokku, kust kadunud koera otsida, ja kirjutab küla gruppi selge postituse sellest, mis juhtus."}, "tags": {"057_d_bog": "g_read", "057_p_board": "g_read", "057_d_opinion": "g_vocab", "057_d_helgi": "g_vocab", "057_d_time": "g_notice", "057_p_join": "g_notice", "057_t_search": "g_use", "057_t_post": "g_use"}},
  "a2b1-058": {"canDo": "Ma loen tormiuudist ja helistan kindlustusse: selgitan põhjuse ja tagajärjega (tormi tõttu, seepärast, nii et), miks kahju tuleb hüvitada.", "goals": {"g_vocab": "Õpilane kasutab tormi ja kahjude sõnu: torm, kask, katus, elekter, rike, sügavkülmik, kahju, kindlustus, põhjus, tagajärg, tõttu, seepärast.", "g_read": "Õpilane saab aru tormiuudisest ja Päästeameti nõuannetest elektrikatkestuse kohta.", "g_notice": "Õpilane seob põhjuse ja tagajärje (sest, kuna, … tõttu, … pärast, seepärast, seetõttu, nii et) ja paneb pärast seepärast / seetõttu ning kuna-lause järel tegusõna kohe.", "g_use": "Õpilane lepib naabriga kokku, kes aia parandab, ja vaidleb kindlustuse otsusele telefonis põhjendatult vastu."}, "tags": {"058_d_news": "g_read", "058_p_cloze": "g_read", "058_t_damage": "g_vocab", "058_d_ready": "g_vocab", "058_d_fix": "g_notice", "058_t_helgi": "g_notice", "058_p_fence": "g_use", "058_t_call": "g_use"}},
  "a2b1-059": {"canDo": "Ma ütlen oma arvamuse koos põhjuse ja näitega ning lepin naabritega koosolekul kokku, mida meie hoovis 300 euroga ära teeme.", "goals": {"g_vocab": "Õpilane kasutab keskkonna ja prügi sõnu: keskkond, keskkonnasõbralik, prügi, sorteerima, biojäätmed, ettepanek, arvamus, kokkulepe.", "g_read": "Õpilane saab aru jäätmenõustaja raadiointervjuust ja loeb naabrite ettepanekuid.", "g_notice": "Õpilane kasutab rektsiooni (hoolima millest, loobuma millest, osalema millel, nõustuma millega) ja reeglite umbisikulist vormi (pannakse, ei panda).", "g_use": "Õpilane ütleb arvamuse mudeliga arvamus + põhjus + näide, kirjutab talgukutse ja lepib koosolekul kokku plaani, mis mahub eelarvesse."}, "tags": {"059_d_radio": "g_read", "059_t_ideas": "g_read", "059_p_sort": "g_vocab", "059_p_invite": "g_vocab", "059_d_verbs": "g_notice", "059_p_rules": "g_notice", "059_d_board": "g_use", "059_t_meeting": "g_use"}},
  "a2b1-060": {"canDo": "Ma sooritan esimese täispika proovieksami Harno B1 vormis ajapiiranguga: loen, kuulan, kirjutan ja räägin; vahekontrolli lävi on 60 % ja eesmärk 80 % igas osas.", "goals": {"g_vocab": "Õpilane tunneb mooduli sõnu ilma, looduse, tormi ja keskkonna kohta: ilmateade, äike, jahe, raba, laudtee, torm, tõttu, seepärast, keskkond, sorteerima, ettepanek, kokkulepe.", "g_read": "Õpilane saab lugemises (33 punkti) vähemalt 20 ja kuulamises (30 punkti) vähemalt 18 punkti; eesmärk on 80 % (27 ja 24 punkti).", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Telefonikõne” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti mooduli vorme: ilma muutumine (läheb jahedamaks), kui- ja enne kui -laused, põhjus ja tagajärg (tõttu, seepärast + tegusõna), rektsioon.", "g_use": "Õpilane saab kirjutamises ja rääkimises (kumbki 20 punkti) vähemalt 12 punkti; eesmärk on 16 punkti; alla vahekontrolli jäänud osale teeb õpetaja moodulites 13–15 järeleaitamise plaani."}, "tags": {"060_p_l1": "g_listen", "060_p_l2": "g_listen", "060_p_l3": "g_listen", "060_p_l4": "g_listen"}},
  "a2b1-061": {"canDo": "Ma loen ühistu teadet ja remondigraafikut ning lepin naabritega kokku, kuidas remondiaja mured lahendada: palun abi, teen ettepaneku ja keeldun viisakalt.", "goals": {"g_vocab": "Õpilane kasutab remondi ja naabrisuhete sõnu: remont, ehitaja, müra, trepikoda, rõdu, kelder, palve, paluma, keelduma, nõus, valmis, vaikus; remondiaja teenuste kuulutused.", "g_read": "Õpilane loeb ühistu esimehe kirja, linnaosa lehe nõuandeid ning remondigraafikut ja ühistu otsuseid ning saab aru maja koosolekust töödejuhatajaga.", "g_notice": "Õpilane palub, teeb ettepaneku ja keeldub (kahjuks + põhjus + uus pakkumine) ning annab palve edasi: palub / soovitab / keelab / lubab teha, on nõus / valmis tegema.", "g_use": "Õpilane tutvustab end uutele naabritele, kirjutab kaheksa minutit naabritest, lepib infolüngaga kokku, millal Heljut aidata, lepib naabritega kokku Karli mure lahenduse, salvestab Karlile häälsõnumi ja kirjutab maja vestlusesse teate."}},
  "a2b1-062": {"canDo": "Ma saan kuuldust aru ja helistan hotelli: palun ja küsin tingiva kõneviisiga viisakalt (sooviksin, kas te saaksite, kas oleks võimalik) ning lahendan broneeringu probleemi.", "goals": {"g_vocab": "Õpilane kasutab reisi ja hotelli sõnu: broneerima, tuba, vastuvõtt, administraator, praam, järjekord, sadam, pilet, hommikusöök, vabandama, võimalik, allahindlus.", "g_read": "Õpilane saab aru Kadri kõnest hotelli, raadiointervjuust viisakusest ja hotelli juhataja häälsõnumist ning loeb hotelli teateid ja juhataja kirja.", "g_notice": "Õpilane moodustab tingiva kõneviisi kõigis isikutes (saaksin, saaksid, saaks, saaksime, saaksite, saaksid; oleks, võiksime) ja muudab käsu viisakaks palveks või sooviks.", "g_use": "Õpilane kirjeldab puhkusefotot, muudab ebaviisaka sõnumi viisakaks, kirjutab üles viisakad palved, vastab küsimusele „Mida sa teeksid?”, helistab hotelli juhatajale, salvestab Helgile häälsõnumi ja täidab hotelli küsimustiku."}},
  "a2b1-063": {"canDo": "Ma loen maja vestlust ja teadet, eristan kindlat infot kuuldud jutust (ta olevat …) ja kirjutan umbes 100-sõnalise jutu sellest, kuidas kuulujutt sündis.", "goals": {"g_vocab": "Õpilane kasutab kuulujutu ja tüli sõnu: kuulujutt, väidetavalt, süüdistama, tüli, arusaamatus, tõde, tegelikult, uskuma, haukuma, jälg, värvima, õiglane; rääkimise tegusõnade rektsioon.", "g_read": "Õpilane loeb maja vestlust, kolme tunnistaja juttu ja Urmase teadet ning saab aru Karli kõnest: kes mida ise nägi ja mis tegelikult juhtus.", "g_notice": "Õpilane eristab kindlat väidet ja kuuldud juttu ning moodustab kaudse kõneviisi oleviku ja mineviku (olevat, tegevat, olevat teinud, ei olevat) ja kasutab sõnu väidetavalt, kuuldavasti, … sõnul.", "g_use": "Õpilane räägib kuulujutust kolm korda, jutustab oma loo, annab Sofiale edasi, mida räägitakse, räägib solvunud Karliga, salvestab loo sõbrale ja kirjutab jutu „Kuidas kuulujutt sündis”."}},
  "a2b1-064": {"canDo": "Ma kuulan mõlemat poolt, aitan kolleegidel kokku leppida ja kirjutan ülemusele 80–100-sõnalise kirja, mida otsustati ja miks.", "goals": {"g_vocab": "Õpilane kasutab kokkuleppe ja kontori sõnu: koosolek, kompromiss, seisukoht, lahendus, otsus, vaidlema, solvuma, aken, konditsioneer, allergia, rahulik, kokkuvõte; numbrid, kuupäevad ja summad kuuldes.", "g_read": "Õpilane saab aru Markuse ja Kristjani häälsõnumitest ning Liisi sõnumist puhkuselt ja loeb Anna näidiskirja ning tööelu ajakirja nõuandeid.", "g_notice": "Õpilane annab edasi teise inimese seisukoha (Markuse sõnul, Kristjan ütles, et…, olevat öelnud), ehitab kirja lõikudest ja seob laused (seepärast, kuna, pärast seda, kui, kokkuvõttes).", "g_use": "Õpilane ütleb oma arvamuse, küsitleb kolme inimest, vastab teemaküsimustele, juhib Markuse ja Kristjani koosolekut, salvestab Liisile kokkuvõtte, teeb kirja plaani ja kirjutab Liisile 80–100-sõnalise kirja."}},
  "a2b1-065": {"canDo": "Ma sooritan suhtlemise ja probleemilahenduse mooduli eksami Harno B1 vormis täispikkuses: loen, kuulan, kirjutan ja räägin ajapiiranguga; eesmärk on vähemalt 80 % igas osas.", "goals": {"g_vocab": "Õpilane tunneb mooduli sõnu remondi, hotelli, kuulujutu ja kokkuleppe kohta: remont, müra, palve, keelduma, broneerima, vastuvõtt, allahindlus, kuulujutt, tegelikult, seisukoht, kompromiss, kokkulepe.", "g_read": "Õpilane saab lugemises (33 punkti) ja kuulamises (30 punkti) vähemalt 80 % punktidest.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Vestlus kontoris” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti mooduli vorme: palub teha / on nõus tegema, tingiv kõneviis viisakas palves, kaudne kõneviis (olevat, olevat teinud) ja siduvad sõnad kirjas.", "g_use": "Õpilane saab kirjutamises (20 punkti) ja rääkimises (20 punkti) vähemalt 80 % punktidest."}, "tags": {"065_p_l1": "g_listen", "065_p_l2": "g_listen", "065_p_l3": "g_listen", "065_p_l4": "g_listen"}},
  "a2b1-066": {"canDo": "Ma loen pere lugu, saan aru, mis sai valmis ja mis jäi pooleli, ning kirjutan umbes 100-sõnalise jutu sellest, kuidas midagi viimasel hetkel valmis sai.", "goals": {"g_vocab": "Õpilane kasutab mälestuste ja ehitamise sõnu: mälestus, jutustama, ehitama, lõpetama, sein, katus, ahi, kivi, naaber, tingimus, pooleli, viimane; ära, läbi ja valmis tegusõnadega.", "g_read": "Õpilane loeb Viktori sauna lugu, ajakirja artiklit saunast ja Oskari mustandit ning saab kuuldust aru, kuidas sauna lugu lõppes.", "g_notice": "Õpilane näitab, et tegevus sai lõpuni: ära, läbi, valmis + täissihitis (luges raamatu läbi, sõi kringli ära, tegi ahju valmis), eituses osastav (ei lugenud raamatut läbi); valmis ei muutu.", "g_use": "Õpilane jutustab Viktori loo kaks korda, kirjutab kaheksa minutit, paneb infolüngaga 1988. aasta ajajoone kokku, valib koos kolm lugu klassi raamatusse, salvestab oma loo ja kirjutab jutu „Ühe ööga valmis”."}},
  "a2b1-067": {"canDo": "Ma saan kuuldust aru ja räägin oma kogemustest täisminevikus (olen käinud, ei ole kunagi proovinud) ning helistan korraldajale, et elavaks raamatuks registreeruda.", "goals": {"g_vocab": "Õpilane kasutab kogemuse sõnu: kogemus, kunagi, julge, kartma, võitma, proovima, lendama, eksima, auhind, esimest korda, elu, konverents.", "g_read": "Õpilane saab aru Oskari videokõnest vanaemaga, elavate raamatute tutvustustest ja raamatukoguhoidja Triinu häälsõnumist ning loeb klassi vanemate vestlust.", "g_listen": "Õpilane saab aru kuulamistekstidest „Oskari videokõne vanaemaga” ja „Triinu sõnum” (lüngad).", "g_notice": "Õpilane eristab kogemust täisminevikus (olen lennanud, ei ole kunagi purjetanud) ja kindla ajaga sündmust lihtminevikus (1996. aastal lendasin) ning moodustab täismineviku jaatuse ja eituse.", "g_use": "Õpilane räägib oma julgest kogemusest kolm korda, küsitleb kolme inimest, vastab küsimustele „Mida sa teeksid?”, helistab raamatukoguhoidjale, salvestab oma raamatu sissejuhatuse ja täidab elava raamatukogu küsimustiku."}, "tags": {"067_d_call": "g_listen", "067_t_voice": "g_listen"}},
  "a2b1-068": {"canDo": "Ma saan kuuldust aru, mis inimese elus mis aastal juhtus, panen sündmused ajajoonele ja kirjutan vanaemale 80–100-sõnalise kirja tema elust ja meie näitusest.", "goals": {"g_vocab": "Õpilane kasutab eluloo sõnu: sündima, kasvama, abielluma, kolima, ülikool, õpilane, sündmus, näitus, hiljem, varsti, samal ajal, foto; aastaarvud kuuldes ja näituse teadetes.", "g_read": "Õpilane saab aru Helgi kõnest oma elu aastatest, raadiosaatest elulugudest ja Viktori loost ning loeb Helgi elulugu, näituse teateid ja kolme pereliikme märkmeid.", "g_listen": "Õpilane saab aru kuulamistekstidest Raadiosaade „Minu lugu ja „Viktori teine elu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane paneb pärast ajasõna või kui-lauset tegusõna õigele kohale, valib liht-, täis- või enneminevikku ja moodustab tegusõnast nimisõna (-ja, -mine, -us).", "g_use": "Õpilane räägib vanast fotost kolm korda, seletab Miale vanaema elu, lepib kokku plakati sündmused, salvestab oma elu ajajoone, teeb kirja plaani ja kirjutab vanaemale 80–100-sõnalise kirja."}, "tags": {"068_d_radio": "g_listen", "068_p_viktor": "g_listen"}},
  "a2b1-069": {"canDo": "Ma loen lugude õhtu kava ja lepin teise lapsevanemaga kokku, kuidas õhtu teine pool läbi viia; jutustan oma loo neljas osas: sündmus, tunne, põhjus ja järeldus.", "goals": {"g_vocab": "Õpilane kasutab loo ja esinemise sõnu: esinema, publik, lava, tunne, põhjus, järeldus, piinlik, üllatunud, naljakas, kurb, kava, järjekord; kooli uudiskirja ja teadaande sõnad.", "g_read": "Õpilane loeb kooli uudiskirja, Sofia lugu ja lugude õhtu kava mustandit ning saab aru Kristeli juhistest lastevanematele.", "g_notice": "Õpilane ehitab loo neljast osast (sündmus, tunne, põhjus, järeldus), kasutab liht-, täis- ja enneminevikku õiges kohas ning paneb pärast siduvat sõna tegusõna teisele kohale.", "g_use": "Õpilane ütleb arvamuse vanade lugude kohta, muudab sõnumi ametlikuks kutseks, kirjutab Kristelile sõnumi, lahendab pagariäris probleemi, vastab teemaküsimustele, lepib kokku õhtu kava, salvestab oma loo ja kirjutab Viktorile kutse."}},
  "a2b1-070": {"canDo": "Ma sooritan mineviku, kogemuste ja jutustamise mooduli eksami Harno B1 vormis täispikkuses: loen, kuulan, kirjutan ja räägin ajapiiranguga; eesmärk on vähemalt 80 % igas osas.", "goals": {"g_vocab": "Õpilane tunneb mooduli sõnu sauna, kogemuste, eluloo ja lugude õhtu kohta: mälestus, ehitama, pooleli, kogemus, kunagi, julge, sündima, kolima, sündmus, esinema, tunne, järeldus.", "g_read": "Õpilane saab lugemises (33 punkti) ja kuulamises (30 punkti) vähemalt 80 % punktidest.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Vestlus pärast lugude õhtut” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti mooduli vorme: ära, läbi ja valmis koos täissihitisega, täisminevik kogemuse jaoks, enneminevik varasema sündmuse jaoks ja sõnajärg pärast ajasõna.", "g_use": "Õpilane saab kirjutamises (20 punkti) ja rääkimises (20 punkti) vähemalt 80 % punktidest."}, "tags": {"070_p_l1": "g_listen", "070_p_l2": "g_listen", "070_p_l3": "g_listen", "070_p_l4": "g_listen"}},
  "a2b1-071": {"canDo": "Ma loen teateid ja kursuse infot tuleviku plaanide kohta ning lepin kaaslasega kokku, mida, millal ja kui tihti me järgmisel aastal teeme.", "goals": {"g_vocab": "Õpilane kasutab tuleviku ja plaanide sõnu: tulevik, eesmärk, plaanima, kavatsema, hakkama, otsustama, saavutama, tähtaeg, samm, varsti, järgmine, mentor; tegusõnad koos käändega (valmistuma eksamiks, keskenduma kuulamisele).", "g_read": "Õpilane loeb firma infolehe artiklit mentorprogrammist, Sofia kirja õpetajale, teateid kontoris ja keelekoolis ning keelekooli kirja ja saab kuuldust aru konsultatsioonist keelekoolis.", "g_notice": "Õpilane räägib tulevikust oleviku ja ajasõnaga, hakkama + ma-vormiga, kavatsema / plaanima + da-vormiga ning muutusest saama / muutuma + -ks ja ütleb tähtaja (reedeks, 10. detsembriks).", "g_use": "Õpilane küsitleb kolme inimest, räägib oma järgmisest aastast kolm korda, leiab infolüngaga õppimise aja, lepib kaaslasega kokku eksamikursuse rühma ja nädala plaani, salvestab oma eesmärgi ja vastab keelekooli kirjale."}},
  "a2b1-072": {"canDo": "Ma loen pere lugu, saan aru möönva kõneviisi lausetest (sõitku, mingu, olgu peale) ja kirjutan umbes 90-sõnalise jutu „Olgu peale!”.", "goals": {"g_vocab": "Õpilane kasutab sõidu ja plaani sõnu: järv, kallas, sõit, kaaslane, muretsema, lubama, nõus olema, üksi, põlv, kilomeeter, olgu peale, täiskasvanud; moodustab sõnu (sõitja, unistus, lubadus) ja tõlgib „пусть …” eesti keelde.", "g_read": "Õpilane loeb Viktori lugu ja pere jutugruppi, saab kuuldust aru, kes on Viktori kaaslane ja kuidas sõit kulgeb, ning võrdleb kolme sõiduplaani.", "g_notice": "Õpilane tunneb ära möönva kõneviisi (sõitku, tulgu, olgu, tehku, ärgu sõitku), ütleb sama mõtte las-lausega (Las ta sõidab) ja paneb las- ja olgu-lause sõnad õigesse järjekorda.", "g_use": "Õpilane jutustab Viktori uudise kaks korda, kirjutab kaheksa minutit, ütleb arvamuse Viktori plaanist, valib koos parima plaani, salvestab loo oma suurest plaanist ja kirjutab jutu „Olgu peale!”."}},
  "a2b1-073": {"canDo": "Ma saan kuuldust aru, mis tingimusel plaan teoks saab, ja kirjutan 80–100-sõnalise kirja, kus on kui-lausetega plaan A ja plaan B.", "goals": {"g_vocab": "Õpilane kasutab tingimuse ja laagri sõnu: tingimus, laager, trenn, treener, koht, maksma, tagasi, juhul kui, ilm, vihm, õnnestuma, võimalus; arvud, kuupäevad ja hinnad kuuldes ning suviste võimaluste kuulutused.", "g_read": "Õpilane saab aru treeneri infost, raadiosaatest plaanist B, Oskari ja isa vestlusest ning treeneri häälsõnumist ja loeb treeneri kirja vanematele.", "g_notice": "Õpilane ühendab laused sõnaga kui, paneb pärast kui-lauset kohe tegusõna, eristab päris võimalust (Kui sajab, treenime sees) ja unistust (Kui saaksin, sõidaksin) ning valib õige vormi.", "g_use": "Õpilane vastab küsimustele kui-lausetega kaks korda, seletab Kadrile treeneri juttu, vastab küsimustele „Mida sa teeksid, kui…?”, helistab klubisse, salvestab oma plaani A ja B ning kirjutab Viktorile kirja."}},
  "a2b1-074": {"canDo": "Ma saan kuuldust aru mentorprogrammi nõuetest, koostan oma tegevusplaani (eesmärk, põhjused, sammud ja tähtajad, plaan B) ja lepin mentoriga kokku esimesed sammud.", "goals": {"g_vocab": "Õpilane kasutab tegevusplaani sõnu: tegevusplaan, mõõtma, toetama, takistus, edu, arenema, vastutama, kohtumine, juhend, osalema, esiteks, põhjus; lahendab plaani sõnade ristsõna ja loeb programmi juhendit.", "g_read": "Õpilane saab aru firma taskuhäälingust ja personalijuhi häälsõnumist ning loeb programmi juhendit ja Sofia plaani mustandit ning kontrollib, kas plaan on realistlik.", "g_listen": "Õpilane saab aru kuulamistekstidest Taskuhääling „Meie nädal ja „Eha häälsõnum osalejatele” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane tunneb ära möönva kõneviisi juhendi lausetes (olgu, võtku, ärgu andku) ja ütleb sama mõtte sõnadega peab, võib, ei tohi; kasutab plaani mudelit otsus + esiteks / teiseks + sammud + kui…, siis… + kokkuvõte.", "g_use": "Õpilane täidab programmi küsimustiku, tutvustab end mentorile kolm korda, kirjutab mentorile teate, vastab teemaküsimustele, lepib mentoriga kokku esimesed sammud, salvestab oma plaani ja kirjutab selle puhtalt."}, "tags": {"074_d_podcast": "g_listen", "074_p_voice": "g_listen"}},
  "a2b1-075": {"canDo": "Ma sooritan tuleviku, plaanide ja eesmärkide mooduli eksami Harno B1 vormis täispikkuses ja ajapiiranguga: loen, kuulan, kirjutan ja räägin; eesmärk on vähemalt 80 % igas osas.", "goals": {"g_vocab": "Õpilane tunneb mooduli sõnu: tulevik, eesmärk, tähtaeg, kaaslane, olgu peale, tingimus, laager, võimalus, takistus, toetama, edu, põhjus.", "g_read": "Õpilane saab lugemises (33 punkti) ja kuulamises (30 punkti) vähemalt 80 % punktidest.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Telefonikõne” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti mooduli vorme: tulevik ajasõnaga ning hakkama, kavatsema ja saama abil, kui-lause sõnajärg ja tingiv kõneviis unistuse jaoks ning tunneb ära möönva kõneviisi (olgu, tehku, mingu).", "g_use": "Õpilane saab kirjutamises (20 punkti) ja rääkimises (20 punkti) vähemalt 80 % punktidest."}, "tags": {"075_p_l1": "g_listen", "075_p_l2": "g_listen", "075_p_l3": "g_listen", "075_p_l4": "g_listen"}},
  "a2b1-076": {"canDo": "Ma räägin oma arvamusest laste telefonide ja ekraaniaja kohta, põhjendan seda ja lepin lastevanemate koosolekul kokku klassi ühise seisukoha.", "goals": {"g_vocab": "Õpilane kasutab arvamuse ja tehnoloogia sõnu: arvamus, minu arvates, arvama, tunduma, kindel, kahtlema, nõustuma, nutitelefon, ekraan, reegel, keelama, vanus; valib arvamuse väljendi selle järgi, kui kindel ta on.", "g_read": "Õpilane saab kuuldust aru Metsade õhtusöögi vaidlusest, raadio tänavaküsitlusest ja klassijuhataja häälsõnumist ning loeb lastevanemate foorumit.", "g_listen": "Õpilane saab aru kuulamistekstidest „Õhtusöök Metsade köögis” ja „Tänavaküsitlus raadios” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane ütleb arvamuse kindluse järgi (olen kindel, ma arvan, mulle tundub, ma kahtlen), paneb pärast „minu arvates” ja ees olevat kuna-lauset tegusõna kohe ning põhjendab sõnadega sest ja kuna.", "g_use": "Õpilane küsitleb kolme inimest, ütleb oma arvamuse kolm korda, vastab teemaküsimustele, lepib lastevanemate koosolekul kokku klassi seisukoha, salvestab oma arvamuse ja vastab klassijuhatajale."}, "tags": {"076_d_kitchen": "g_listen", "076_p_poll": "g_listen"}},
  "a2b1-077": {"canDo": "Ma loen artiklit ja kolleegide arvamusi kaugtöö kohta, võrdlen kolme võimalust ja kirjutan juhatajale 90–110-sõnalise ettepaneku.", "goals": {"g_vocab": "Õpilane kasutab võrdlemise ja töö sõnu: võrdlema, võrreldes, kaugtöö, kontor, eelis, puudus, mugav, rahulik, säästma, eelistama, kolleeg, vaikne; ühendab väljendid õige käändega ja leiab kuulutustest sobiva töökoha.", "g_read": "Õpilane loeb firma infolehe artiklit kaugtöö küsitlusest ja kolme variandi kirjeldust ning saab kuuldust aru kolleegide häälsõnumitest ja raadiosaatest e-riigist.", "g_listen": "Õpilane saab aru kuulamistekstidest „Kolleegide häälsõnumid” ja „Raadio: kaugtöö ja e-riik” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane võrdleb keskvõrde ja sõnaga kui, ülivõrdega (kõige …), väljenditega sama … kui, võrreldes + -ga ja erinevalt + -st ning parandab võrdluse vead (nagu → kui, paremam → parem).", "g_use": "Õpilane võrdleb kahte töökohta kolm korda, kirjutab kaheksa minutit oma tööpäevast, vahetab infot kahe variandi kohta, paneb tiimiga variandid järjekorda, salvestab oma võrdluse ja kirjutab Liisile ettepaneku."}, "tags": {"077_d_voices": "g_listen", "077_p_radio": "g_listen"}},
  "a2b1-078": {"canDo": "Ma saan kuuldust aru argumentidest linna ja hoovi teemal ning kirjutan maja infolehele arvamusloo, kus on kaks argumenti põhjuse, näite ja järeldusega.", "goals": {"g_vocab": "Õpilane kasutab argumendi ja linnaelu sõnu: põhjendama, näiteks, järeldus, seepärast, seega, hoov, mänguväljak, ohutu, liiklus, kiirus, hääletama, linnaosa; valib sidesõna põhjuse, tagajärje, näite või vastanduse jaoks.", "g_read": "Õpilane saab kuuldust aru linnaosa uudisest kaasava eelarve kohta ja raadiointervjuust kiiruse kohta ning loeb kuulajate kommentaare ja Urmase artiklit maja infolehes.", "g_listen": "Õpilane saab aru kuulamistekstidest „Linnaosa uudised” ja „Intervjuu kiirusest” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane ehitab argumendi arvamus → põhjus → näide → järeldus, paneb pärast seepärast, seega ja näiteks tegusõna kohe ning täpsustab kes- ja mis-lausega (kellel, millest, mida).", "g_use": "Õpilane jutustab uudise kaks korda ümber, seletab naabrile linnaosa plaani, kirjutab Karli postituse viisakaks, helistab linnaosa valitsusse, salvestab oma raadiokommentaari ja kirjutab ning toimetab arvamusloo."}, "tags": {"078_d_news": "g_listen", "078_p_siret": "g_listen"}},
  "a2b1-079": {"canDo": "Ma loen naabrite ettepanekuid, arutan elanike koosolekul viisakalt hoovi tulevikku ja lepin teistega kokku kompromissi.", "goals": {"g_vocab": "Õpilane kasutab arutelu sõnu: arutelu, ettepanek, kompromiss, kokkulepe, koosolek, otsus, poolt, vastu, eelarve, seisukoht, viisakas, vaidlema; leiab teravale lausele viisaka vastuse ja tõlgib viisakad laused.", "g_read": "Õpilane loeb ühistu esimehe kirja, kutset koosolekule ja ettepanekute lehte koos hindadega ning saab kuuldust aru esimehe häälsõnumist enne koosolekut.", "g_listen": "Õpilane saab aru kuulamistekstidest „Raadio: kuidas naabritega kokku leppida?” ja „Urmase häälsõnum enne koosolekut” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane ütleb arvamuse viisakalt tingivas kõneviisis (ma arvaksin, oleks parem, me võiksime, kas te oleksite nõus), nõustub osaliselt ja esitab vastuküsimuse (Aga mis saab siis, kui…?).", "g_use": "Õpilane proovib naabriga probleemi kaks korda lahendada, täidab maja küsitluse, vastab küsimustele „Mida sa teeksid?”, lepib koosolekul kokku kompromissi, salvestab koosoleku kokkuvõtte ja kirjutab otsuse maja jutugruppi."}, "tags": {"079_d_radio": "g_listen", "079_p_voice": "g_listen"}},
  "a2b1-080": {"canDo": "Ma sooritan teise täispika proovieksami Harno B1 vormis ajapiiranguga: loen, kuulan, kirjutan ja räägin; vahekontrolli lävi on 75 % ja eesmärk 80 % igas osas.", "goals": {"g_vocab": "Õpilane tunneb mooduli sõnu arvamuse, võrdlemise ja põhjendamise kohta: arvamus, minu arvates, kahtlema, reegel, võrdlema, eelis, puudus, kaugtöö, järeldus, seepärast, kompromiss, ettepanek.", "g_read": "Õpilane saab lugemises (33 punkti) vähemalt 25 ja kuulamises (30 punkti) vähemalt 23 punkti; eesmärk on 80 % (27 ja 24 punkti).", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Telefonikõne” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti mooduli vorme: tegusõna kohe pärast „minu arvates”, kuna-lauset, seepärast ja seega; keskvõrre + kui, kõige, võrreldes + -ga; kes- ja mis-laused; viisakas tingiv kõneviis.", "g_use": "Õpilane saab kirjutamises ja rääkimises (kumbki 20 punkti) vähemalt 15 punkti; eesmärk on 16 punkti; alla läve jäänud osa vaatab õpetaja enne moodulit 17 õpilasega läbi."}, "tags": {"080_p_l1": "g_listen", "080_p_l2": "g_listen", "080_p_l3": "g_listen", "080_p_l4": "g_listen"}},
  "a2b1-081": {"canDo": "Ma loen maja ja tänava teateid, seletan neid uuele naabrile ning helistan värvifirmasse ja küsin umbisikulise vormiga, millal ja kuidas töid tehakse.", "goals": {"g_vocab": "Õpilane kasutab maja ja teadete sõnu: teade, trepikoda, elanik, naaber, kelder, toru, ahi, remont, värvima, koristama, keelatud, palve; leiab kuulutustest majale sobiva teenuse.", "g_read": "Õpilane loeb lugu Ruslani esimesest nädalast ja maja teadetest ning saab kuuldust aru linnaosa raadiouudistest ja Tiina häälsõnumist.", "g_notice": "Õpilane moodustab umbisikulise tegumoe olevikus, minevikus ja eituses (vahetatakse, värviti, ei köeta) ja paneb täissihitise umbisikulises lauses nimetavasse (torud vahetatakse).", "g_use": "Õpilane seletab teateid uuele naabrile, kirjutab kaheksa minutit oma ümbruse teadetest, vastab teemaküsimustele, helistab värvifirmasse, salvestab oma maja teadete seletuse ja vastab Tiinale."}},
  "a2b1-082": {"canDo": "Ma loen ametlikku kirja ja juhendit asutusele kirjutamise kohta, võrdlen kolme võimalust asutusega suhelda ja kirjutan linnaosa valitsusele 90–110-sõnalise ametliku kirja.", "goals": {"g_vocab": "Õpilane kasutab asjaajamise sõnu: asutus, taotlus, avaldus, vastus, otsus, lisa, selgitus, pöörduma, esitama, allkirjastama, tutvuma, menetlema; jagab ametliku kirja lugemise nõuanded enne, ajal ja pärast lugemist.", "g_read": "Õpilane loeb juhendit asutusele kirjutamise kohta ja linnaosa valitsuse vastust, saab kuuldust aru e-teenuses taotluse esitamise sammudest, täidab Sofia kirja lauseosadega ja võrdleb kolme võimalust asutusega suhelda.", "g_notice": "Õpilane kasutab tegusõnu õige käändega (pöörduma asutuse poole, vastama kirjale, aru saama kirjast, tutvuma dokumendiga, sõltuma otsusest) ja moodustab tegusõnast nimisõna (taotlus, taotleja, otsus, vastus).", "g_use": "Õpilane küsitleb paarilist asjaajamise kohta, jutustab oma asjaajamise loo, vahetab infot kahe taotluse kohta, lepib kokku, kuidas asutusega suhelda, lahendab linnaosa vastuvõtul probleemi, ütleb sõnavõtus arvamuse e-teenuste kohta ja kirjutab linnaosa valitsusele kirja."}},
  "a2b1-083": {"canDo": "Ma saan raadiosaatest ja telefonikõnest aru, kuidas keeleeksamile registreerida ja riigi e-teenust turvaliselt kasutada, annan kuuldu edasi ning koostan ja tutvustan koos naabritega uue elaniku meelespea.", "goals": {"g_vocab": "Õpilane kasutab eksami ja asjaajamise sõnu: eksam, registreerima, tähtaeg, dokument, isikukood, sõnaraamat, hilinema, tunnistus, osa, ruum, kinnitama, kaasa; täidab sõnumid sobivate sõnadega.", "g_read": "Õpilane saab kuuldust aru raadiosaatest eksamist, Ruslani kõnest Sotsiaalkindlustusametisse ja Tiina jutust majakoosolekul ning loeb turvalise asjaajamise meelespead.", "g_listen": "Õpilane saab aru kuulamistekstidest Raadio „Päevateema”: eksamiks valmis?, „Ruslan helistab Sotsiaalkindlustusametisse” ja „Tiina koosolekul: mida uus elanik peab tegema?” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane annab kuuldut edasi: umbisikuline minevik (öeldi, soovitati), et- ja kas-lause, isiku muutus (ma → ta), soovitas + da-tegevusnimi ja kellegi sõnul.", "g_use": "Õpilane räägib saatest kolm korda, vastab „Mida sa teeksid?” küsimustele ja eksamineerija küsimustele avalike teenuste kohta, täidab linnaosa küsimustiku, paneb koos naabriga meelespea punktid järjekorda ja tutvustab meelespead naabritele."}, "tags": {"083_d_radio": "g_listen", "083_p_ska": "g_listen", "083_t_meeting": "g_listen"}},
  "a2b1-084": {"canDo": "Ma kirjutan majale 50-sõnalise teate talgutest ja sõbrale 90–110-sõnalise kirja ning toimetan oma kirja rubriigi järgi.", "goals": {"g_vocab": "Õpilane kasutab kirja ja teate sõnu: kiri, sõnum, tervitus, sisu, lause, parandama, viisakas, talgud, kutsuma, kirjeldama, teema, osalema; eristab teate, sõbrakirja ja ametliku kirja väljendeid ning kordab mooduli sõnu ristsõnas.", "g_read": "Õpilane saab kuuldust aru raadiointervjuust ja kümnest lühikesest teatest, loeb Lena kirja, Sofia mustandit ja talgute küsitluse tulemusi ning leiab iga lõigu ülesande.", "g_listen": "Õpilane saab aru kuulamistekstidest „Raadio: kuidas kirjutada head teadet ja kirja?” ja „Kümme lühikest teadet” (küsimused kuuldu kohta).", "g_notice": "Õpilane ehitab teate ja kirja (pöördumine, lõigud, lõpp), ühendab laused sidesõnadega (kõigepealt, seejärel, peale selle, lõpuks, seepärast), valib sina- või teie-vormi ja parandab mustandi vead.", "g_use": "Õpilane võrdleb kodu talvel ja kevadel, ütleb arvamuse paberi ja ekraani kohta, kirjutab Ruslani sõnumi viisakaks, lepib Tiinaga kokku teate sisu, salvestab suulise kutse naabritele, kirjutab teate majale ja kirja Lenale ning toimetab selle."}, "tags": {"084_d_radio": "g_listen", "084_p_clips": "g_listen"}},
  "a2b1-085": {"canDo": "Ma lahendan Harno B1 lugemise ja kirjutamise osa ajapiiranguga: neli lugemisülesannet 50 minutiga ning küsimustiku ja isikliku kirja 35 minutiga; eesmärk on vähemalt 80 % kummaski osas.", "goals": {"g_vocab": "Õpilane tunneb mooduli sõnu teadete, eksami, kirjade ja õppimise kohta: teade, elanik, remont, tulemus, eesmärk, valmistuma, tähtaeg, dokument, kiri, tervitus, talgud, viisakas.", "g_read": "Õpilane lahendab Harno B1 lugemise neli ülesannet (olukord ↔ kuulutus, artikkel valikvastustega, sõnapangaga lünktekst, lauseosade pank) ajapiiranguga ja saab vähemalt 27 punkti 33-st.", "g_notice": "Õpilane kasutab õigesti mooduli vorme: umbisikuline tegumood, kuuldu edasiandmine (öeldi, ta ütles, et…), tegusõnade rektsioon ja sidesõnad koos õige sõnajärjega.", "g_use": "Õpilane täidab küsimustiku ja kirjutab sõbrale 100-sõnalise isikliku kirja ajapiiranguga, saab kirjutamises vähemalt 16 punkti 20-st ning parandab oma kirja rubriigi järgi."}},
  "a2b1-086": {"canDo": "Ma saan häälsõnumist ja raadiointervjuust aru, mis muutus, helistan keelekooli, selgitan viisakalt oma probleemi ja lepin kokku uue lahenduse.", "goals": {"g_vocab": "Õpilane kasutab muudatuse ja probleemi sõnu: muudatus, tühistama, asendama, pakkuma, lahendus, kaebus, vabandama, võimalus, kokkulepe, eksamineerija, partner, salvestama; sorteerib kõne laused ja ühendab tegusõna sobiva jätkuga.", "g_read": "Õpilane saab kuuldust aru keelekooli ja Olena häälsõnumist ning raadiointervjuust suulise eksami kohta (Harno B1 kuulamine 4) ja loeb keelekooli tingimusi.", "g_listen": "Õpilane saab aru kuulamistekstidest „Krista häälsõnum: mis muutus?” ja „Kuidas käib suuline eksam?” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane räägib probleemist viisakalt: kahjuks ei sobi…, kas oleks võimalik…, ma sooviksin…, kas te saaksite…; kasutab umbisikulist minevikku (jäeti ära, pakuti) ja kontrollib kuuldut (kas ma saan õigesti aru, et…).", "g_use": "Õpilane proovib kõnet keelekooli kaks korda, jutustab katki läinud plaanist, kirjutab pahase sõnumi viisakaks, avaldab arvamust pühade, töö ja plaanide kohta, helistab Kristale ja lepib kokku lahenduse, salvestab loo lahendatud probleemist ja kinnitab kokkuleppe kirjalikult."}, "tags": {"086_d_voice": "g_listen", "086_p_radio": "g_listen"}},
  "a2b1-087": {"canDo": "Ma loen näidisjuttu ja leian selle osad, kavandan oma loo ning kirjutan 90–110-sõnalise jutu etteantud pealkirjaga, kasutades minevikuvorme ja ajasõnu.", "goals": {"g_vocab": "Õpilane kasutab jutu sõnu: jutt, pealkiri, sündmus, juhtuma, äkki, lõpuks, tunne, mälestus, kirjeldama, plaan, komme, unustama; kirjutab kaheksa minutit järjest ja paneb ajasõnaga laused õigesse järjekorda.", "g_read": "Õpilane loeb Igori eksamijuttu tema esimesest jõululaupäevast Eestis, teksti Eesti jõulukommetest ja Hanna nõuandeid, leiab Sofia jutu iga lause ülesande ja saab kuuldust aru kuulaja loost raadios.", "g_notice": "Õpilane eristab lihtminevikku ja enneminevikku (läksin – olin unustanud), ühendab laused sidesõnadega (kuigi, sest, pärast seda kui, nii et), paneb tegusõna ajasõna järel teisele kohale ja parandab jutu vead.", "g_use": "Õpilane küsitleb kolme inimest meeldejäänud pühade kohta, vastab eksamineerija küsimustele pühade ja tähistamise kohta (Harno B1 rääkimine 1), valib koos Olenaga loo idee, jutustab oma loo salvestusel, kirjutab plaani ja 100-sõnalise jutu „Püha, mida ma ei unusta”."}},
  "a2b1-088": {"canDo": "Ma loen pere sõnumeid ja teksti võidupühast ja jaanipäevast, avaldan arvamust, lepin perega kokku, kus ja kuidas suurt pidu tähistada, ning tutvustan oma kodumaa püha.", "goals": {"g_vocab": "Õpilane kasutab peo ja arutelu sõnu: tähistama, pidu, ettepanek, arvamus, nõustuma, eelistama, kompromiss, otsustama, külaline, kutse, köögijuhataja, lõke; seob arutelu väljendid nende ülesandega ja täidab Viktori kirja.", "g_read": "Õpilane loeb pere grupivestlust, populaarteaduslikku teksti võidupühast ja jaanipäevast ning Viktori kolme kava ning saab kuuldust aru kümnest lühikesest sõnumist ja teatest.", "g_notice": "Õpilane avaldab arvamust ja teeb ettepaneku tingiva kõneviisiga (mis oleks, kui teeksime…, ma eelistaksin…, me võiksime…), nõustub osaliselt, pakub kompromissi (kui…, siis…) ja kinnitab otsuse (lepime kokku, et…).", "g_use": "Õpilane kirjutab sõnumi pere grupivestlusse, jutustab peost 4-3-2 meetodil, vastab „Mida sa teeksid?” küsimustele, täidab Viktori küsimustiku, vahetab infot peo ajakava jaoks, lepib kokku jaanipäeva kava (Harno B1 rääkimine 1, kokkulepe), peab ettekande oma kodumaa pühast ja kirjutab kutse."}},
  "a2b1-089": {"canDo": "Ma sooritan kolmanda täispika proovieksami Harno B1 vormis ajapiiranguga: loen, kuulan, kirjutan ja räägin ning saan teada, kas olen eksamiks valmis — eesmärk on vähemalt 80 % igas osas.", "goals": {"g_read": "Õpilane lahendab Harno B1 lugemise (33 punkti, 50 min) ja kuulamise (30 punkti) neli ülesannet ajapiiranguga; eksamiks valmis on ta, kui saab lugemises vähemalt 27 ja kuulamises vähemalt 24 punkti.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Telefonikõne” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti mooduli 18 vorme: viisakas tingiv kõneviis (kas te saaksite…, ma eelistaksin…), umbisikuline minevik (jäeti ära), lihtminevik ja enneminevik jutus, ajasõna järel tegusõna teisel kohal, kokkuleppe väljendid.", "g_use": "Õpilane kirjutab teate ja isikliku kirja ning sooritab rääkimise osa (sissejuhatus, teemaküsimused, kokkulepe, telefonikõne); eksamiks valmis on ta, kui saab kirjutamises ja rääkimises vähemalt 16 punkti 20-st."}, "tags": {"089_p_l1": "g_listen", "089_p_l2": "g_listen", "089_p_l3k": "g_listen", "089_p_l4": "g_listen"}},
  "a2b1-090": {"canDo": "Ma sooritan kursuse lõpphindamise Harno B1 vormis ajapiiranguga: loen, kuulan, kirjutan ja räägin; kursuse tunnistuse saan, kui igas osas on vähemalt 80 %, ning sean endale järgmise eesmärgi.", "goals": {"g_read": "Õpilane lahendab lõpphindamise lugemise (33 punkti) ja kuulamise (30 punkti) osa ajapiiranguga ning saab kursuse tunnistuseks vähemalt 27 ja 24 punkti.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Vestlus kontoris” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab kursuse B1 grammatikat: umbisikuline tegumood, tingiv kõneviis, enneminevik, kuuldu edasiandmine (et-, kas-lause), rektsioon ja sõnajärg.", "g_use": "Õpilane täidab küsimustiku ja kirjutab jutu, sooritab rääkimise osa, saab kirjutamises ja rääkimises vähemalt 16 punkti 20-st ning koostab oma järgmise eesmärgi ja kordamis- või edasiõppimise kava."}, "tags": {"090_p_l1": "g_listen", "090_p_l2": "g_listen", "090_p_l3": "g_listen", "090_p_l4": "g_listen"}},
  // the e-exam format (b1/eeksam.js mock 1, b1/eeksamHarjutus.js practice): the listening lessons report g_listen
  "a2b1-ee1-l": {"canDo": "Ma saan aru arvamustest, monoloogist, lühikestest teadetest ja intervjuust ning kirjutan kuuldu põhjal lünka sõna või arvu.", "goals": {"g_listen": "Õpilane saab aru e-eksami kuulamistekstide põhimõttest ja detailidest (5 ülesannet, 35 küsimust) ning saab vähemalt 60 % õigeid vastuseid.", "g_use": "Õpilane kirjutab kuulamise ajal märkmeid ja hindab pärast, mis aitas."}, "tags": {"ee1_l_11": "g_listen", "ee1_l_12": "g_listen", "ee1_l_13": "g_listen", "ee1_l_14": "g_listen", "ee1_l_15": "g_listen"}},
  "a2b1-ee-p-l": {"canDo": "Ma tunnen e-eksami kolme kuulamisülesannet: sobitan kõneleja ja väite, otsustan, kas väide on õige või vale, ja kirjutan kuuldud sõna või arvu lünka.", "goals": {"g_listen": "Õpilane saab aru, mida eri inimesed liikumisest räägivad, leiab intervjuust õiged ja valed väited ning kirjutab teatest arvud ja sõnad.", "g_use": "Õpilane räägib oma liikumisharjumustest ja põhjendab, mida tahaks muuta."}, "tags": {"eep_l_1": "g_listen", "eep_l_2": "g_listen", "eep_l_3": "g_listen"}},
};
